window.VI_TRANSLATIONS_B = {"1":{"q":"Sau khi web search agent và document analysis agent hoàn thành nhiệm vụ của mình, coordinator gọi (invoke) synthesis agent. Tuy nhiên, synthesis agent phản hồi rằng nó không thể hoàn thành nhiệm vụ vì không có research findings nào được cung cấp. Nguyên nhân nào có khả năng nhất gây ra vấn đề này?","o":{"A":"Synthesis agent cần các tool có thể lấy trực tiếp kết quả từ conversation history của các agent khác.","B":"Context window của synthesis agent không đủ lớn để chứa các output kết hợp từ cả hai agent trước đó.","C":"Các subagent cần chia sẻ chung một API connection để cho phép chia sẻ context tự động giữa các lần gọi (invocation).","D":"Coordinator đã không đưa các output từ những agent trước đó vào prompt của synthesis agent."}},"2":{"q":"Khi nghiên cứu chủ đề \"renewable energy adoption,\" web search agent trả về các số liệu thống kê gần đây (2024: 35% adoption) trong khi document analysis agent trích xuất dữ liệu từ các báo cáo nội bộ (2022: 18% adoption). Synthesis agent đánh dấu nhầm đây là các nguồn mâu thuẫn nhau thay vì nhận ra rằng dữ liệu này cho thấy sự tăng trưởng theo thời gian. Thay đổi nào sẽ giúp synthesis agent diễn giải chính xác nhất các khác biệt về mặt thời gian (temporal differences) như vậy?","o":{"A":"Yêu cầu các subagent phải đưa ngày xuất bản hoặc ngày thu thập dữ liệu vào trong structured output của chúng.","B":"Hướng dẫn synthesis agent luôn coi dữ liệu mới nhất là có giá trị tin cậy nhất (authoritative) và đặt các phát hiện cũ hơn vào một phụ lục lịch sử (historical appendix) riêng.","C":"Thêm một conflict resolution agent để tự động loại bỏ dữ liệu cũ khi đã có dữ liệu mới hơn cho cùng một metric.","D":"Cấu hình web search agent chỉ trả về các kết quả trong vòng 6 tháng gần nhất."}},"3":{"q":"Người dùng phản ánh rằng các báo cáo cuối cùng đôi khi thiếu chiều sâu (depth) ở một số chủ đề con (subtopics) cụ thể. Điều tra cho thấy document analysis agent thường xuyên phát hiện ra các khoảng trống (gaps)—ví dụ, ghi nhận rằng \"the retrieved sources discuss API authentication but lack details on token refresh patterns\"—nhưng theo pipeline nghiêm ngặt (strict pipeline) hiện tại, phát hiện này không thể được hành động theo (not actionable) vì bước search đã hoàn tất. Thay đổi kiến trúc (architectural change) nào là hiệu quả nhất?","o":{"A":"Để analysis agent báo cáo các khoảng trống (gap) cụ thể cho coordinator, từ đó coordinator kích hoạt các tìm kiếm có mục tiêu (targeted search) và gọi lại (re-invoke) analysis cho đến khi đủ thông tin.","B":"Thêm một research planning agent trước giai đoạn tìm kiếm để phân rã (decompose) các chủ đề thành các câu hỏi con cụ thể.","C":"Để synthesis agent gắn confidence score cho từng phần và đánh dấu (flag) các khu vực có độ bao phủ (coverage) chưa đủ để xem xét thủ công.","D":"Để coordinator xem xét output của analysis để tìm dấu hiệu của khoảng trống (gap indicator), và khi phát hiện gap thì gọi lại (re-invoke) search với các truy vấn (query) dựa trên gap đã phát hiện."}},"4":{"q":"Multi-agent research pipeline của bạn bị crash sau khi xử lý được 12 trong số 28 documents. Web search agent đã xác định được các nguồn liên quan, document analyzer đã xử lý xong một phần (partially complete), còn synthesizer thì đã bắt đầu nhận diện pattern. Bạn cần resume việc xử lý mà không lặp lại công việc đã làm hoặc làm mất đi độ chính xác (fidelity) của các phát hiện trước đó. Phương pháp quản lý state nào sẽ cân bằng (balance) giữa information fidelity và context efficiency khi khôi phục (restore) agent state?","o":{"A":"Để mỗi agent lưu (persist) một structured export ra một vị trí đã biết trước. Khi resume, coordinator sẽ load manifest và chèn (inject) trạng thái liên quan vào prompt của các agent.","B":"Lưu lại conversation log của coordinator chứa toàn bộ các lần ủy quyền tác vụ (task delegation) và phản hồi, rồi cung cấp log này cho các agent khi resume.","C":"Để mỗi agent tự duy trì một file trạng thái persistent riêng và tự tải lại (reload) độc lập vào đầu mỗi session.","D":"Lập chỉ mục (index) toàn bộ output của các agent vào một shared vector store. Khi resume, mỗi agent truy vấn vector store bằng semantic search để lấy lại các phát hiện liên quan trước đó."}},"5":{"q":"Synthesis agent hoàn thành lượt xử lý đầu tiên (initial pass) nhưng đánh dấu rằng ba câu hỏi nghiên cứu quan trọng vẫn chưa được trả lời vì web search agent và document analysis agent không tìm thấy thông tin liên quan về các chủ đề con cụ thể đó. Hiện tại, coordinator tiến thẳng đến report generation, tạo ra các báo cáo có độ bao phủ (coverage) không đầy đủ. Thay đổi nào sẽ cải thiện hiệu quả nhất tính đầy đủ (completeness) của nghiên cứu?","o":{"A":"Để coordinator đánh giá output của synthesis để tìm khoảng trống (gap), sau đó ủy quyền lại (re-delegate) cho web search và document analysis với các truy vấn có mục tiêu (targeted query) trước khi gọi lại synthesis.","B":"Tăng độ rộng (breadth) ban đầu của các truy vấn gửi tới web search và document analysis để giảm xác suất bỏ sót thông tin liên quan.","C":"Để report generation agent ghi chú lại những câu hỏi nghiên cứu nào chưa được trả lời, để người dùng hiểu được giới hạn của output cuối cùng.","D":"Cho synthesis agent quyền truy cập trực tiếp vào các web search tool để nó có thể tự chủ (autonomously) lấp đầy các khoảng trống kiến thức mà không cần trả quyền điều khiển lại cho coordinator."}},"6":{"q":"Khi phân tích các vụ án pháp lý phức tạp có trích dẫn nhiều tiền lệ (precedents), document analysis subagent xử lý từng precedent một cách tuần tự (sequentially). Một vụ án mang tính bước ngoặt (landmark case) trích dẫn 12 precedents mất hơn 3 phút để phân tích hoàn tất. Đâu là cách hiệu quả nhất để giảm độ trễ (latency) này trong khi vẫn giữ được khả năng giám sát (monitor) và debug hệ thống của coordinator?","o":{"A":"Cho phép document analysis subagent tự động sinh (spawn) các subagent chuyên biệt của riêng nó khi gặp các case có nhiều citation.","B":"Triển khai một message queue, trong đó các tác vụ phân tích tiền lệ (precedent analysis) được xử lý bất đồng bộ (asynchronously) bởi một pool worker agent.","C":"Tạo một hệ thống phân cấp agent đệ quy (recursive agent hierarchy), trong đó các analysis agent chia nhỏ công việc cho các child agent cho đến khi đạt độ chi tiết (granularity) từng tiền lệ đơn lẻ.","D":"Để coordinator sinh (spawn) song song các document analysis subagent, mỗi subagent xử lý một tập con các tiền lệ (precedent), sau đó tổng hợp (aggregate) kết quả trước khi synthesis."}},"7":{"q":"Việc giám sát production (production monitoring) cho thấy research phase mất nhiều thời gian hơn dự kiến. Phân tích cho thấy coordinator gọi (invoke) web search subagent, chờ phản hồi, sau đó gọi document analysis subagent và chờ tiếp. Hai tác vụ này độc lập với nhau—không tác vụ nào cần đến kết quả đầu ra của tác vụ kia. Bạn nên sửa đổi hệ thống như thế nào để chạy các subagent này đồng thời (concurrently)?","o":{"A":"Chuyển cả hai subagent sang dùng model tier Haiku để giảm thời gian thực thi (execution time) của từng subagent.","B":"Tạo một async orchestration layer bên ngoài agent để sinh (spawn) các luồng (thread) song song, mỗi luồng chạy một cặp coordinator-subagent riêng, sau đó tổng hợp (aggregate) kết quả.","C":"Thêm hướng dẫn chi tiết vào system prompt của coordinator giải thích lợi ích về hiệu năng (performance) của việc thực thi song song (parallel execution) và yêu cầu nó gọi cả hai subagent cùng lúc.","D":"Cấu trúc lại coordinator để phát ra cả hai lệnh gọi Task tool (cho web search và document analysis) trong cùng một response message thay vì qua các lượt hội thoại (conversation turn) riêng biệt."}},"8":{"q":"Các đợt rà soát production (production reviews) cho thấy việc xử lý uncertainty trong các báo cáo cuối cùng thiếu nhất quán. Đôi khi các phát hiện mâu thuẫn nhau giữa các subagent được tổng hợp (synthesize) thành một phát biểu duy nhất đầy chắc chắn (làm mất đi sắc thái quan trọng), những lúc khác báo cáo lại rào đón quá mức (over-hedge) với quá nhiều điều kiện ràng buộc (excessive qualifications), trở nên không hữu ích. Khi web search agent trả về \"Industry analysts estimate $50B market size (methodology...)\" và document analysis agent trả về \"peer-reviewed study estimates $35B (15%, 95% CI),\" coordinator hoặc chọn đại một trong hai, hoặc đưa ra các phát biểu mơ hồ như \"the market is $35B-$50B depending on factors.\" Phương pháp tiếp cận có hệ thống (systematic approach) nào giải quyết vấn đề này tốt nhất?","o":{"A":"Cấu hình các subagent chỉ báo cáo những phát hiện đạt ngưỡng confidence cao, lọc bỏ thông tin không chắc chắn trước khi nó đến được coordinator.","B":"Thêm một verification subagent để đối chiếu chéo (cross-reference) các phát hiện giữa các nguồn, chỉ chuyển sang synthesis những claim được xác nhận (corroborated) bởi ít nhất hai nguồn độc lập.","C":"Hướng dẫn synthesis agent cấu trúc báo cáo với các phần rõ ràng phân biệt giữa những phát hiện đã được xác lập vững chắc (well-established) và những phát hiện còn gây tranh cãi (contested), đồng thời giữ nguyên cách mô tả nguồn gốc (source characterization) và bối cảnh phương pháp luận (methodological context) ban đầu.","D":"Triển khai một confidence calibration layer để chuẩn hóa (normalize) các cách diễn đạt mức độ không chắc chắn (uncertainty) của subagent thành các điểm xác suất chuẩn hóa (standardized probability score, 0.0-1.0), sau đó tính trung bình có trọng số (weight-average) các phát hiện theo điểm độ tin cậy (reliability score) đã tính để tạo ra một synthesis có cơ sở thống kê (statistically grounded)."}},"9":{"q":"Trong môi trường production, bạn nhận thấy rằng các truy vấn fact-checking đơn giản (ví dụ: \"What year was the Paris Climate Agreement signed?\") đi qua tuần tự cả bốn subagent, tiêu tốn hơn 40 giây. Điều này có thể chấp nhận được vì complex comparative research được hưởng lợi từ toàn bộ pipeline. Query distribution của bạn đa dạng và liên tục thay đổi khi người dùng khám phá ra các ứng dụng mới. Đâu là cách tiếp cận hiệu quả nhất để tối ưu hóa cho độ phức tạp truy vấn (query complexity) khác nhau?","o":{"A":"Triển khai pattern-based routing để phân loại truy vấn theo cấu trúc (single-fact so với comparative so với analytical) và ánh xạ (map) mỗi loại tới một tổ hợp subagent được định trước.","B":"Huấn luyện (train) một query complexity classifier trên dữ liệu lịch sử đã gán nhãn để dự đoán tổ hợp subagent tối ưu, huấn luyện lại định kỳ khi các pattern truy vấn thay đổi.","C":"Để coordinator phân tích từng truy vấn và quyết định linh động (dynamically) subagent nào cần gọi dựa trên đánh giá của nó về yêu cầu của truy vấn.","D":"Tạo một fast-path cho các câu hỏi mang tính sự kiện (factual) để bỏ qua hoàn toàn các subagent, còn tất cả các truy vấn khác thì đi qua toàn bộ pipeline để đảm bảo tính đầy đủ (thoroughness) của nghiên cứu."}},"10":{"q":"Một người dùng đang mở rộng hệ thống nghiên cứu vượt ra ngoài một web search agent duy nhất bằng cách thêm các nguồn dữ liệu chuyên biệt. Họ thêm một financial API agent trả về JSON có cấu trúc (structured) chứa margins và growth rates; một news monitoring agent trả về các bản tóm tắt dạng văn xuôi (prose summaries) về các diễn biến gần đây; và một patent analysis agent trả về các danh sách có cấu trúc về công nghệ. Synthesis agent kết hợp các dữ liệu này thành các executive briefings. Hiện tại, nó chuyển đổi mọi thứ thành bullet points, khiến các so sánh tài chính (financial comparisons) mất đi tính rõ ràng dạng bảng (tabular clarity) và các bản tóm tắt tin tức mất đi mạch văn tự nhiên (narrative flow). Thay đổi nào sẽ cải thiện chất lượng briefing tốt nhất?","o":{"A":"Cập nhật synthesis agent để hiển thị (render) mỗi loại nội dung một cách phù hợp — dữ liệu tài chính dưới dạng bảng (table), tin tức dưới dạng văn xuôi (prose), và danh sách kỹ thuật dưới dạng các điểm có cấu trúc (structured points).","B":"Thêm một format conversion layer giữa các subagent và synthesis để chuyển đổi toàn bộ output sang một dạng biểu diễn trung gian chung (common intermediate representation, ví dụ Markdown) nhằm hỗ trợ việc render linh hoạt hơn.","C":"Chuẩn hóa toàn bộ output của subagent về JSON với các field cho mọi loại dữ liệu để đảm bảo tính nhất quán khi xử lý bằng chương trình (programmatic consistency) trong toàn bộ pipeline.","D":"Chuẩn hóa toàn bộ output của subagent thành các đoạn tóm tắt văn xuôi (prose summary) với văn phong đồng nhất để duy trì giọng văn báo cáo điều hành (executive voice) nhất quán bất kể tài liệu nguồn là gì."}},"11":{"q":"Coordinator agent có AgentDefinitions được cấu hình cho cả bốn subagent chuyên biệt, mỗi cái đều có descriptions, prompts, và tool restrictions phù hợp. Trong quá trình testing, bạn nhận thấy coordinator suy luận (reason) chính xác về thời điểm cần delegate—nó tạo ra các thông điệp như \"I'll ask the web search agent to find sources on this topic\"—nhưng không có subagent execution nào thực sự xảy ra. Coordinator sau đó tiếp tục như thể việc delegation đã xảy ra và tiếp tục với thông tin không đầy đủ. Logs không cho thấy lỗi nào. Nguyên nhân nào có khả năng nhất?","o":{"A":"Context isolation của subagent nghĩa là các task description từ coordinator không tự động đến được các subagent; bạn cần cấu hình chuyển tiếp context (context forwarding) rõ ràng trong Claude AgentOptions.","B":"Thiết lập max_tokens của coordinator quá thấp, khiến lệnh gọi Task tool bị cắt ngắn (truncated) trước khi tham số subagent type kịp được chỉ định.","C":"Cấu hình allowed Tools của coordinator không bao gồm \"Task\", nên dù nó có thể suy luận (reason) về việc ủy quyền (delegation), nó không thể gọi tool cần thiết để sinh (spawn) subagent.","D":"Các AgentDefinitions được cấu hình đúng, nhưng system prompt của coordinator không liệt kê rõ ràng các loại subagent khả dụng, khiến model không biết rằng chúng có thể được gọi."}},"12":{"q":"Trong production, các báo cáo cuối cùng thường xuyên chứa các claim không có source attribution phù hợp. Điều tra cho thấy trong khi web search agent và document analysis agent gắn citation vào output của chúng một cách chính xác, synthesis agent lại mất dấu (lose track) về việc nguồn nào hỗ trợ cho kết luận nào khi kết hợp các phát hiện lại với nhau. Thay đổi kiến trúc nào là hiệu quả nhất?","o":{"A":"Thêm một bước verification, trong đó report generator dùng semantic similarity matching để đối chiếu với nguồn gốc (original source) nhằm tái tạo (reconstruct) xem claim nào đến từ tài liệu nào.","B":"Để coordinator chèn (inject) các tiền tố định danh nguồn (source identifier prefix) vào văn bản trước mỗi lần bàn giao (handoff), sau đó phân tích (parse) các tiền tố này khi tạo báo cáo để tái tạo citation.","C":"Duy trì transcript đầy đủ của toàn bộ tương tác giữa các subagent và thêm một citation-resolution agent để phân tích log và xác định nguồn gốc (attribution) trước khi tạo báo cáo.","D":"Yêu cầu tất cả các subagent xuất ra structured claim-source mapping mà synthesis agent phải giữ nguyên và hợp nhất (merge) khi kết hợp các phát hiện từ nhiều nguồn."}},"13":{"q":"Sau khi web search subagent và document analysis subagent hoàn thành nhiệm vụ của mình, coordinator cần spawn synthesis subagent để tổng hợp (synthesize) các phát hiện. Đâu là cách tiếp cận đúng để cung cấp cho synthesis subagent thông tin mà nó cần?","o":{"A":"Cung cấp cho subagent các tool definition cho phép nó yêu cầu (request) output từ các subagent khác thông qua callback.","B":"Đưa toàn bộ phát hiện (findings) từ cả hai subagent trực tiếp vào prompt của synthesis subagent.","C":"Truyền các reference identifier và cấu hình cho subagent quyền đọc (read access) vào một shared memory store nơi các subagent khác đã lưu (deposit) kết quả của chúng.","D":"Sinh (spawn) subagent chỉ với một mô tả tác vụ (task description) ngắn gọn, dựa vào cơ chế kế thừa context tự động (automatic context inheritance) từ coordinator."}},"14":{"q":"Web search agent đã thu thập được một số nguồn liên quan cho một chủ đề nghiên cứu. Document analysis agent giờ cần kiểm tra các nguồn này. Thông tin luân chuyển (flow) giữa hai subagent chuyên biệt này như thế nào?","o":{"A":"Coordinator agent nhận output của web search agent và đưa các phát hiện liên quan vào prompt khi gọi document analysis agent.","B":"Các agent giao tiếp qua một message queue theo hướng sự kiện (event-driven), trong đó document analysis agent đăng ký (subscribe) nhận các sự kiện hoàn tất (completion event) của web search.","C":"Web search agent trực tiếp gọi document analysis agent, sử dụng các nguồn đã tìm được (discovered sources) làm tham số (parameter).","D":"Cả hai agent đều truy cập một shared memory store, trong đó web search agent ghi các phát hiện vào và document analysis agent đọc ra."}},"15":{"q":"Sau khi web search agent tìm được 25 nguồn (120K tokens nội dung thô), document analysis agent trích xuất các insight chính (15K tokens), và synthesis agent tạo ra một bản nháp tường thuật mạch lạc (coherent narrative draft) (3K tokens), coordinator phải truyền context cho report generation agent để tạo ra kết quả cuối cùng kèm theo citation nguồn phù hợp. Chiến lược truyền context (context-passing strategy) nào mang lại sự cân bằng tốt nhất giữa tính đầy đủ (completeness) và hiệu quả (efficiency)?","o":{"A":"Chỉ truyền bản nháp synthesis (synthesis draft) và để một pipeline post-processing riêng biệt khớp các claim với nguồn và chèn citation sau khi báo cáo đã được tạo.","B":"Truyền toàn bộ context tích lũy (accumulated context) từ tất cả các agent trước đó.","C":"Truyền bản nháp synthesis cùng với một structured source index ánh xạ các claim quan trọng tới URL nguồn và các đoạn trích dẫn liên quan (relevant excerpts) của chúng.","D":"Truyền một bản tóm tắt cô đọng (condensed summary) của tất cả các giai đoạn trước đó, giữ lại các phát hiện chính và chỉ gán nguồn theo tên (by name only)."}},"16":{"q":"Search products tool của bạn truy vấn một external catalog API trả về kết quả phân trang (paginated results) (50 items mỗi request). Logs production cho thấy các truy vấn thường khớp với hơn 200 products, và thiết kế hiện tại tự động fetch tất cả các trang (auto-fetches all pages) gây ra độ trễ 15-20 giây. Bạn nên thiết kế lại việc xử lý pagination như thế nào?","o":{"A":"Tạo các tool riêng biệt là search và fetch more results để phục vụ phân trang (pagination).","B":"Triển khai xếp hạng mức độ liên quan (relevance ranking) ở phía server và chỉ trả về 50 mục liên quan nhất (top 50).","C":"Thêm một tham số max pages (mặc định: 2) để kiểm soát số trang được lấy (fetch) nội bộ.","D":"Trả về trang đầu tiên cùng với tổng số kết quả khớp (total match count) và cursor cho các trang tiếp theo."}},"17":{"q":"Search Flights tool của bạn gọi một external airline API, thỉnh thoảng trả về lỗi 503 Service Unavailable. Đâu là cách hiệu quả nhất để xử lý lỗi này trong tool implementation của bạn?","o":{"A":"Trả về danh sách chuyến bay rỗng như thể tìm kiếm đã thành công nhưng không tìm thấy chuyến bay phù hợp nào.","B":"Ghi log lỗi nội bộ và trả về một response rỗng, để model tiếp tục mà không có dữ liệu chuyến bay.","C":"Trả về một thông báo lỗi trong tool result giải thích rằng dịch vụ đang tạm thời không khả dụng.","D":"Tự động thử lại (retry) request tối đa 5 lần với exponential backoff trước khi trả kết quả về cho agent."}},"18":{"q":"MCP server của bạn triển khai một tool check_availability truy vấn một external calendar API. Trong quá trình testing, bạn gặp phải ba tình huống lỗi: (1) tool được gọi với một request bị lỗi định dạng (malformed), thiếu tham số user_email bắt buộc; (2) calendar API trả về lỗi 404 vì user được chỉ định không tồn tại trong hệ thống calendar; (3) calendar API trả về lỗi 503 vì service tạm thời không khả dụng. Mỗi lỗi nên được báo cáo như thế nào theo thiết kế xử lý lỗi (error handling design) của MCP?","o":{"A":"Báo cáo cả ba lỗi dưới dạng tool result với isError: true","B":"Báo cáo lỗi 1 và 2 dưới dạng JSON-RPC protocol error, báo cáo lỗi 3 dưới dạng tool result với isError: true","C":"Báo cáo lỗi 1 dưới dạng JSON-RPC protocol error, báo cáo lỗi 2 và 3 dưới dạng tool result với isError: true","D":"Báo cáo cả ba lỗi dưới dạng JSON-RPC protocol error."}},"19":{"q":"Documents (query) tool của bạn trả về kết quả dưới dạng \"Found 3 documents: Q2 Budget Proposal, Q2 Budget Forecast, Annual Review\". Bạn muốn agent có thể thực hiện các thao tác tiếp theo như document (4, multi) và doc (24, multi). Định dạng trả về (return format) nào sẽ hỗ trợ tốt nhất cho các multi-step workflow này?","o":{"A":"Các URL mà người dùng có thể click để mở tài liệu trong trình duyệt của họ.","B":"Dữ liệu có cấu trúc (structured data) chứa document ID và metadata cho từng kết quả.","C":"Một JSON array chứa các tiêu đề tài liệu (document title) được trích xuất từ kết quả tìm kiếm.","D":"Các mô tả chi tiết hơn, dễ đọc đối với con người (human-readable), bao gồm cả kích thước (size) và tác giả (author)."}},"20":{"q":"Agent của bạn có quyền truy cập vào hơn 50 API connector chuyên biệt cho các external service khác nhau. Khi connector library phát triển lớn hơn, độ chính xác trong việc chọn tool (tool selection accuracy) giảm xuống còn 58%. Bạn thiết kế một tool search_connectors(description) để tìm các connector phù hợp, nhưng trong quá trình testing, agent thường xuyên bỏ qua việc search và gọi trực tiếp connector (thường không chính xác), hoặc search nhưng lại chọn sai connector từ các kết quả đã lọc. Bạn nên thiết kế tool composition pattern như thế nào để giải quyết cả hai vấn đề này?","o":{"A":"Thiết kế các connector có sẵn cơ chế validation về tính tương thích (compatibility), trả về các thông báo lỗi mô tả rõ ràng (descriptive error) khi request không khớp.","B":"Thiết kế một composite tool find_and_execute(description, params) để tìm kiếm và ngay lập tức thực thi connector khớp nhất.","C":"Nâng cao mô tả (description) của tất cả các connector với các ví dụ sử dụng (usage sample) chi tiết, các trường hợp biên (edge case), và yêu cầu đầu vào (input requirement). Thêm các few-shot example minh họa đúng quy trình (workflow) tìm kiếm rồi mới sử dụng (search-then-use).","D":"Thiết kế search_connectors để tự động (dynamically) thêm các connector khớp vào danh sách tool khả dụng của agent. Các connector ban đầu không khả dụng (unavailable) và tồn tại (persist) sau khi được phát hiện (discovered)."}},"21":{"q":"Tool publish article của bạn gọi một CMS API bên ngoài, API này thỉnh thoảng trả về các lỗi tạm thời (transient errors) (network timeout, lỗi 503) và các lỗi không tạm thời (non-transient errors) (403 permission denied, 422 validation failure). Hiện tại, mọi lỗi đều được trả trực tiếp về cho agent, khiến agent retry các lỗi non-transient và lãng phí lượt (turns) vào những lỗi sẽ không bao giờ thành công. Bạn nên phân chia trách nhiệm xử lý lỗi (error-handling) giữa phần triển khai tool và agent như thế nào?","o":{"A":"Xử lý tất cả lỗi bên trong tool: triển khai cơ chế retry với exponential backoff cho mọi loại lỗi, và chỉ báo lỗi (failure) cho agent sau khi đã hết một số lần retry cố định.","B":"Xử lý các lỗi tạm thời (transient errors) (timeout, lỗi 503) bằng cách tự động retry ngay bên trong phần triển khai tool, và báo các lỗi không tạm thời (non-transient errors) (permission denied, validation failures) cho agent kèm thông báo mô tả rõ ràng để agent có thể thực hiện hành động khắc phục.","C":"Báo ngay tất cả lỗi cho agent kèm ngữ cảnh (context) chi tiết, để agent tự quyết định lỗi nào cần retry và retry bao nhiêu lần - giữ cho phần triển khai tool ở trạng thái stateless và đơn giản.","D":"Triển khai một trình xử lý lỗi (error handler) chung, bắt tất cả exception và trả về thông báo chung chung \"tool unavailable - try again later\", giúp agent không phải tiếp xúc với sự phức tạp của lỗi."}},"22":{"q":"Tool remove_team_member của bạn sử dụng tham số dry_run: boolean để xem trước (preview) tác động trước khi thực thi. Giám sát production cho thấy agent bỏ qua bước preview trong 15% số lần gọi bằng cách gọi trực tiếp với dry_run=false. Bạn cần đảm bảo mọi thao tác xóa (removal) đều phải được preview trước và được user xác nhận rõ ràng. Đâu là cách tiếp cận đáng tin cậy nhất?","o":{"A":"Thêm validation phía server (server-side) chỉ cho phép dry_run=false khi trước đó, trong vòng 60 giây, đã có một lệnh gọi dry_run=true với các tham số (parameters) giống hệt.","B":"Thay bằng hai tool: preview_remove_member trả về chi tiết tác động (impact) và một confirmation token dùng một lần; execute_remove_member yêu cầu token đó, ràng buộc việc thực thi với đúng hành động đã được xem trước (previewed).","C":"Gắn annotation cho tool là yêu cầu xác nhận (requiring confirmation), và cấu hình lớp điều phối (orchestration layer) để yêu cầu người dùng phê duyệt (approval) trước khi chuyển tiếp bất kỳ lệnh gọi nào đến các tool đã được annotate.","D":"Thêm hướng dẫn chi tiết và few-shot examples vào mô tả (description) của tool, yêu cầu agent luôn gọi với dry_run=true trước và chờ người dùng xác nhận trước khi gọi với dry_run=false."}},"23":{"q":"Agent xử lý expense reimbursement của bạn xử lý các yêu cầu của nhân viên bằng một tool process reimbursement. Chính sách công ty yêu cầu các khoản hoàn tiền (reimbursement) trên $500 phải được phê duyệt trước khi giải ngân. Agent xử lý hàng trăm yêu cầu mỗi ngày, và bạn cần việc thực thi ngưỡng (threshold enforcement) này phải chống giả mạo (tamper-proof) bất kể agent được prompt như thế nào. Điều gì đảm bảo ngưỡng phê duyệt $500 không thể bị bỏ qua (bypass)?","o":{"A":"Tool process_reimbursement nhận một tham số approved_by_manager. System prompt hướng dẫn agent chỉ đặt giá trị này là true sau khi đã xác nhận rằng một manager đã phê duyệt yêu cầu. Một script audit chạy hàng đêm sẽ rà soát tất cả các khoản hoàn tiền (reimbursement) có approved_by_manager được đặt là true.","B":"Cung cấp hai tool: auto_reimburse (giới hạn cố định $500, hard-coded) và manager_approval. Thêm hướng dẫn chi tiết trong system prompt yêu cầu agent kiểm tra số tiền (amount) và sử dụng tool phù hợp. Thêm một PostToolUse hook để ghi log tool nào đã được gọi phục vụ mục đích audit.","C":"Tool process_reimbursement nhận amount và details, và tự thực thi ngưỡng (threshold) giới hạn ở bên trong; các khoản <$500 được tự động giải ngân (auto-disbursed) và tool trả về xác nhận thành công. Các khoản >$500 khiến tool tạo một yêu cầu phê duyệt đang chờ xử lý (pending approval request) và trả về trạng thái cho biết đang chờ manager xem xét (review).","D":"Triển khai việc kiểm tra ngưỡng (threshold) trong một PreToolUse hook để kiểm tra tham số amount trước khi process_reimbursement thực thi. Nếu amount vượt quá $500, hook sẽ sửa đổi context để thêm cờ (flag) requires_approval: true, mà tool sẽ kiểm tra trước khi giải ngân."}},"24":{"q":"Hệ thống order management của bạn cần các tool cho ba thao tác riêng biệt: issuing refunds (yêu cầu amount và reason), canceling orders (yêu cầu reason), và reshipping orders (yêu cầu shipping address). Mỗi thao tác đều dùng chung tham số order_id nhưng có các yêu cầu bổ sung khác nhau. Trong quá trình testing, bạn nhận thấy rằng với thiết kế hiện tại, agent thường xuyên bỏ sót (omit) các tham số bắt buộc hoặc đưa vào các tham số không liên quan. Thay đổi thiết kế nào sẽ cải thiện hiệu quả nhất độ chính xác của tham số (parameter accuracy)?","o":{"A":"Tách thành ba tool riêng biệt (mỗi tool chỉ định nghĩa các tham số cần thiết cho thao tác (operation) cụ thể đó).","B":"Giữ một tool thống nhất (unified) duy nhất với tất cả tham số được đánh dấu là optional, nhưng thêm few-shot examples trong system prompt để minh họa các tổ hợp tham số đúng cho từng operation.","C":"Giữ một tool thống nhất duy nhất nhưng thêm các điều kiện (conditionals) if-then-else trong JSON Schema để bắt buộc các tham số như amount chỉ là required khi operation type là \"refund\".","D":"Giữ một tool thống nhất duy nhất với một tham số object operation lồng nhau (nested), có cấu trúc bên trong thay đổi theo operation type, được mô tả trong tool description."}},"25":{"q":"Tool portfolio value của bạn trả về tổng giá trị portfolio đầu tư của user. Bạn đang cân nhắc giữa việc trả về một structured JSON object với các field rõ ràng so với trả về thông tin dưới dạng một formatted text string. Ưu điểm chính của việc sử dụng structured output với các field được định nghĩa rõ ràng là gì?","o":{"A":"JSON có cấu trúc (structured) tiêu tốn ít token hơn đáng kể so với ngôn ngữ tự nhiên, giúp giảm đáng kể chi phí API.","B":"Agent có thể trích xuất (extract) các giá trị cụ thể một cách đáng tin cậy mà không cần phải parse văn bản dạng tự do (free form text), giảm lỗi trong các thao tác tiếp theo.","C":"JSON có cấu trúc được model xử lý theo cách tất định (deterministically), cải thiện đáng kể độ chính xác khi trích xuất giá trị.","D":"JSON schema tự động validate rằng API bên dưới đã trả về dữ liệu đúng trước khi agent xử lý dữ liệu đó."}},"26":{"q":"Agent scheduling của bạn sử dụng get_available_slots(date, provider_id) để lấy các khung giờ hẹn còn trống (open appointment times), sau đó dùng book_appointment(provider_id, slot_time, patient_id) để đặt giữ (reserve) một khung giờ. Các ticket hỗ trợ cho thấy 15% số lần đặt lịch (booking attempts) thất bại với lỗi \"slot no longer available\" vì một user khác đã đặt khung giờ đó trong khoảng thời gian giữa lúc kiểm tra tình trạng trống (availability check) và lúc gọi booking. Bạn nên redesign hai tool này như thế nào?","o":{"A":"Sửa book_appointment để trả về thông tin lỗi (failure) chi tiết, bao gồm các khung giờ (slot) thay thế hiện đang trống khi slot được yêu cầu không khả dụng, giúp agent có thể retry với một thời điểm khác.","B":"Giữ cả hai tool nhưng thêm logic retry vào system prompt của agent, hướng dẫn agent gọi lại get_available_slots và chọn một thời điểm khác nếu việc đặt lịch (booking) thất bại.","C":"Thêm một tool hold_slot(provider_id, slot_time) tạo một chỗ giữ (reservation) tạm thời trong 60 giây, yêu cầu agent gọi tool này giữa bước kiểm tra tính khả dụng (availability) và bước đặt lịch (booking).","D":"Gộp cả hai tool thành một tool duy nhất find_and_book_appointment, thực hiện kiểm tra tính khả dụng và đặt lịch một cách atomic (atomically), trả về hoặc là booking đã được xác nhận hoặc các lựa chọn thay thế khả dụng."}},"27":{"q":"Agent của bạn có một tool log_workout nhận exercise_type (string), value (number), và measurement (string). Giám sát production cho thấy agent thường xuyên truyền vào các tổ hợp không khớp — dùng measurement: \"reps\" cho các bài cardio như chạy bộ, hoặc measurement: \"miles\" cho các bài strength như bench press. Các bài tập của bạn tự nhiên chia thành hai nhóm: cardio (đo bằng thời gian hoặc quãng đường) và strength (đo bằng reps và sets). 23% số lần gọi tool có tổ hợp không hợp lệ. Cách tiếp cận nào sẽ giảm thiểu các lỗi này hiệu quả nhất?","o":{"A":"Triển khai validation phía server, trả về các thông báo lỗi mô tả rõ ràng cho các tổ hợp không hợp lệ, cho phép agent retry với các chỉnh sửa (corrections).","B":"Thêm ràng buộc enum lên measurement, giới hạn giá trị chỉ còn \"minutes\", \"miles\", \"reps\", hoặc \"sets\" để ngăn các chuỗi (string) measurement tùy ý.","C":"Thêm các ví dụ rõ ràng vào tool description để minh họa các tổ hợp hợp lệ (ví dụ: \"Với chạy bộ: dùng minutes hoặc miles. Với hít đất (push-ups): dùng reps\") kèm ràng buộc cho từng loại bài tập (exercise category).","D":"Tách thành log_cardio_workout (với tham số duration_minutes hoặc distance_miles) và log_strength_workout (với tham số reps và sets)."}},"28":{"q":"MCP server của bạn bao gồm các tool archive_file(file_id) và delete_file(file_id). Log production cho thấy agent gọi delete_file khi user yêu cầu \"remove old backups,\" trong khi chính sách yêu cầu phải archive các file backup. Cả hai tool hiện đều có description tối giản: \"Archives a file\" và \"Deletes a file.\" Thay đổi nào cải thiện trực tiếp nhất việc lựa chọn tool (tool selection)?","o":{"A":"Thêm một bước xác nhận (confirmation), yêu cầu người dùng gõ \"CONFIRM DELETE\" trước khi delete_file thực thi.","B":"Triển khai validation phía server, từ chối các lệnh gọi delete_file đối với các file được gắn thẻ (tagged) là backup, trả về thông báo lỗi gợi ý sử dụng archive_file.","C":"Mở rộng tool description để làm rõ các use case, thêm hướng dẫn kiểu như \"Không dùng cho file backup\" vào delete_file.","D":"Thêm few-shot examples vào system prompt để minh họa rằng các yêu cầu có liên quan đến \"backup\" hoặc \"old\" nên dùng archive_file."}},"29":{"q":"Tool delete_contact của agent CRM của bạn xử lý các yêu cầu như \"delete the duplicate entry for Acme Corp.\" Database chứa các bản ghi có tên tương tự nhau (ví dụ: \"Acme Corp,\" \"Acme Corporation,\" \"ACME Corp Inc.\"), và số liệu phân tích cho thấy 8% các lượt xóa (deletion) bị hoàn tác (reverse) trong vòng 24 giờ do xác định nhầm bản ghi. Người dùng cũng phàn nàn rằng luồng xác nhận nhiều bước (multi-step confirmation flow) hiện tại gây quá nhiều vướng víu (friction) cho các tác vụ dọn dẹp thông thường. Cách tiếp cận nào giảm tỷ lệ lỗi hiệu quả nhất trong khi vẫn duy trì hiệu suất làm việc (workflow efficiency)?","o":{"A":"Hiển thị các bản ghi (record) khớp cùng các trường (field) giúp phân biệt, và yêu cầu xác nhận bằng một cú click (single-click confirmation) về đối tượng (target) dự định trước khi thực hiện xóa.","B":"Yêu cầu người dùng cung cấp chính xác record ID từ giao diện CRM (CRM Interface) thay vì dùng các tham chiếu bằng ngôn ngữ tự nhiên đến tên liên hệ (contact).","C":"Triển khai (deploy) cơ chế phát hiện trùng lặp (duplicate detection) tự động, xác định và gộp (merge) các bản ghi có khả năng trùng lặp, loại bỏ nhu cầu yêu cầu xóa thủ công.","D":"Triển khai soft-delete với thời gian có thể khôi phục (recovery window) 30 ngày, để người dùng có thể hoàn tác (undo) sai sót mà không làm chậm quy trình (workflow) xóa."}},"30":{"q":"Sau khi triển khai (implement) tool use với các định nghĩa schema nghiêm ngặt (strict schema definitions), lỗi cú pháp JSON (JSON syntax errors) đã được loại bỏ hoàn toàn, nhưng 5% các lượt extraction vẫn cho ra JSON hợp lệ với mảng rỗng (empty arrays) hoặc giá trị null cho các field bắt buộc như citations và methodology. Việc kiểm tra thủ công (spot-checking) cho thấy các tài liệu nguồn thực sự chứa thông tin này, nhưng ở nhiều định dạng khác nhau — inline citations so với bibliographies, các mục methodology riêng so với chi tiết được lồng vào trong phần Introduction. Đâu là cách hiệu quả nhất để khắc phục các lỗi này?","o":{"A":"Sửa schema để đặt citations và methodology thành optional, và gắn cờ (flag) các bản ghi không đầy đủ (incomplete) để review thủ công thay vì làm validation thất bại (fail).","B":"Xây dựng một lớp xử lý hậu kỳ (post-processing) dựa trên regex, quét tài liệu nguồn để tìm các mẫu (pattern) citation và các từ khóa (keyword) methodology, điền vào các trường trống khi model không trích xuất được.","C":"Thêm few-shot examples minh họa việc trích xuất từ các tài liệu có cấu trúc đa dạng - cho thấy cách nhận diện citations ở nhiều định dạng khác nhau và xác định vị trí chi tiết methodology trong nhiều loại section khác nhau.","D":"Triển khai logic retry, gửi lại yêu cầu khi validation phát hiện các trường required bị trống."}},"31":{"q":"Hệ thống xử lý các đánh giá sản phẩm (product reviews) bằng tool use với một schema được định nghĩa sẵn: rating (integer 1-5), pros (string array), cons (string array), và overall_sentiment (enum: positive, negative, neutral). Testing cho thấy hai vấn đề với các review ngắn hoặc mơ hồ (chiếm khoảng 20% dataset): (1) với các review như \"Great product!\", Claude bịa ra (fabricate) các pros và cons cụ thể thay vì chỉ ra rằng thông tin đó không được nêu rõ ràng, và (2) với các review mang tính mỉa mai (sarcastic) như \"Well that was… interesting\", Claude chọn sentiment một cách tùy tiện vì không có lựa chọn nào cho các trường hợp mơ hồ (ambiguous cases). Thay đổi nào giải quyết tốt nhất cả hai vấn đề này?","o":{"A":"Đặt pros và cons thành các trường optional, và thêm \"neutral\" và \"unclear\" vào enum sentiment.","B":"Cho phép mảng (array) rỗng cho pros/cons là output hợp lệ, và thêm \"unclear\" vào enum sentiment.","C":"Thêm một trường extraction_confidence (0.0-1.0) cho mỗi giá trị, và lọc bỏ các output có bất kỳ confidence nào thấp hơn một ngưỡng (threshold).","D":"Cho phép giá trị null cho pros/cons, và thêm \"unclear\" vào enum sentiment."}},"32":{"q":"Hệ thống extraction của bạn triển khai cơ chế tự động retry khi validation thất bại. Ở mỗi lần retry, lỗi validation cụ thể sẽ được thêm vào prompt. Cách tiếp cận retry-with-error-feedback này giải quyết được hầu hết các lỗi trong vòng 2-3 lần thử. Với dạng lỗi (failure pattern) nào thì việc retry thêm sẽ ÍT hiệu quả nhất?","o":{"A":"Model trích xuất \"et al.\" cho các đồng tác giả (co-author) khi danh sách đầy đủ chỉ tồn tại trong một tài liệu bên ngoài, không có trong input.","B":"Model trích xuất số lượng trích dẫn (citation count) dưới dạng chuỗi (string) được định dạng theo locale (\"1234\") trong khi schema yêu cầu kiểu integer.","C":"Model trích xuất ngày tháng dưới dạng chuỗi datetime theo ISO 8601 (\"2003-03-15T00:00:00Z\") trong khi schema chỉ yêu cầu phần ngày (date portion) (YYYY-MM-DD).","D":"Model trích xuất từ khóa (keyword) dưới dạng một object lồng nhau (nested) được tổ chức theo category, trong khi schema yêu cầu một mảng (array) phẳng các string."}},"33":{"q":"Hệ thống extraction hóa đơn (invoice extraction) của bạn sử dụng tool use với các JSON schema nghiêm ngặt. Lỗi cú pháp JSON không bao giờ xảy ra, nhưng 12% lượt extraction thất bại ở bước validation ngữ nghĩa (semantic validation) — ví dụ, tổng các line item amount không khớp với total, hoặc vendor ID không đúng định dạng hợp lệ. Các trường hợp lỗi này hiện đang được chuyển sang manual review. Đâu là cách tiếp cận hiệu quả nhất để giảm khối lượng manual review trong khi vẫn duy trì độ chính xác?","o":{"A":"Retry việc trích xuất tối đa 3 lần khi validation thất bại (fail), chấp nhận kết quả đầu tiên vượt qua (pass) validation.","B":"Triển khai logic xử lý hậu kỳ (post-processing) để tự động sửa các lỗi phổ biến, chẳng hạn như tính lại (recalculate) tổng (total) từ các dòng chi tiết (line item) khi tổng không khớp.","C":"Khi validation thất bại, gửi một yêu cầu tiếp theo (follow-up) kèm tài liệu, kết quả trích xuất, và các lỗi validation để model tự sửa (correction).","D":"Thêm các ràng buộc (constraint) schema chặt chẽ hơn kèm mô tả trường (field description) chi tiết để ngăn model tạo ra các giá trị không hợp lệ ngay từ đầu."}},"34":{"q":"Nhóm của bạn đang trích xuất dữ liệu có cấu trúc (structured data) từ 50.000 hợp đồng pháp lý cũ (legacy legal contracts) trong thời hạn hai tuần. Testing ban đầu với 500 tài liệu mẫu cho thấy 82% pass JSON schema ngay ở lần thử đầu tiên, trong khi 18% còn lại thất bại vì nhiều vấn đề khác nhau — thiếu các field bắt buộc, ngày tháng sai định dạng (malformed dates), và xác định sai các bên liên quan (parties). Các tài liệu thất bại thường cần những điều chỉnh (refinement) nhắm đúng vào failure mode cụ thể của chúng trước khi extraction thành công. Chiến lược batch processing nào là tiết kiệm chi phí nhất trong khi vẫn đáp ứng được deadline?","o":{"A":"Chia tài liệu thành 10 batch tuần tự, mỗi batch 5.000 tài liệu, phân tích kết quả và tinh chỉnh (refine) prompt giữa các batch để cải thiện chất lượng trích xuất một cách tăng dần.","B":"Gửi toàn bộ 50.000 tài liệu qua batch API, sau đó gửi các trích xuất thất bại trong các batch kế tiếp - tinh chỉnh prompt giữa mỗi batch - cho đến khi tất cả tài liệu vượt qua validation.","C":"Dùng real-time API cho toàn bộ 50.000 tài liệu vì cửa sổ xử lý (processing window) 24 giờ của batch API tạo ra rủi ro về deadline không thể chấp nhận được.","D":"Xử lý 2.000 tài liệu mẫu (sample) qua real-time API để xác định các mẫu lỗi (failure pattern) và tinh chỉnh prompt, sau đó xử lý toàn bộ 50.000 tài liệu bằng batch với các prompt đã được tối ưu."}},"35":{"q":"Pipeline extraction của bạn xử lý các hợp đồng thường xuyên có amendment (điều khoản sửa đổi). Khi một hợp đồng chứa cả điều khoản gốc lẫn amendment sau này (ví dụ: điều khoản gốc quy định \"30-day payment terms\" trong khi Amendment 1 thay đổi thành \"45 days\"), model trích xuất không nhất quán, khi thì lấy giá trị này khi thì lấy giá trị kia, mà không có chỉ dẫn nào cho biết giá trị nào thực sự áp dụng. Đâu là cách tiếp cận hiệu quả nhất để cải thiện độ chính xác extraction cho các tài liệu có amendment?","o":{"A":"Tiền xử lý (preprocess) tài liệu bằng một classifier để xác định và loại bỏ các phần (section) đã bị thay thế (superseded) trước bước trích xuất chính.","B":"Triển khai validation sau trích xuất (post-extraction) bằng pattern matching để phát hiện các điều khoản sửa đổi (amendment) và gắn cờ các trích xuất đó để review thủ công.","C":"Thiết kế lại schema để các trường bị sửa đổi (amended field) có thể ghi nhận nhiều giá trị, mỗi giá trị kèm vị trí nguồn (source location) và ngày hiệu lực (effective date).","D":"Thêm hướng dẫn trong prompt để luôn trích xuất giá trị sửa đổi (amendment) gần nhất và bỏ qua các điều khoản (term) gốc đã bị thay thế."}},"36":{"q":"Hệ thống của bạn cần trích xuất chi tiết sự kiện (event details) từ các lời mời trên calendar (calendar invitations) và xuất ra JSON tuân thủ nghiêm ngặt một schema gồm các field title, date, time, location, và attendees. Các hệ thống downstream sẽ từ chối bất kỳ JSON nào bị lỗi định dạng (malformed) hoặc không tuân thủ schema (non-conformant). Cách tiếp cận nào mang lại độ tuân thủ schema (schema compliance) đáng tin cậy nhất?","o":{"A":"Định nghĩa một tool có schema mục tiêu (target) làm tham số đầu vào (input parameters), và để Claude gọi tool đó với dữ liệu đã trích xuất.","B":"Điền sẵn (pre-fill) phần đầu response của Claude bằng một dấu ngoặc nhọn mở để buộc output ở dạng JSON, sau đó hoàn thiện và parse response.","C":"Thêm hướng dẫn kiểu như \"Chỉ output JSON hợp lệ khớp chính xác với schema\" và triển khai logic retry để prompt lại khi việc parse JSON thất bại.","D":"Đưa hướng dẫn định dạng JSON chi tiết cùng schema mục tiêu vào prompt, sau đó parse phần text response của Claude như JSON."}},"37":{"q":"Schema của bạn bao gồm một field skills: string[]. Giám sát production cho thấy ba vấn đề về tính nhất quán: (1) các cụm từ ghép (compound phrases) như \"Python and SQL\" đôi khi được giữ nguyên là một entry, đôi khi bị tách ra; (2) các skill được ngụ ý (implied) nhưng không nêu rõ đôi khi vẫn xuất hiện trong kết quả extraction; (3) các tài liệu tương tự nhau lại cho ra độ dài mảng (array length) khác biệt rất lớn (5-10 so với 40+ entry). Prompt hiện tại của bạn chỉ ghi \"Extract skills mentioned.\" Cải tiến nào hiệu quả nhất?","o":{"A":"Thêm ràng buộc: \"Trích xuất tối đa 10-20 kỹ năng (skill), mỗi entry một skill, chỉ những skill được nêu tên rõ ràng (explicitly named).\"","B":"Thêm bước chuẩn hóa (normalization) sau trích xuất, ánh xạ (map) các skill vào một hệ phân loại (taxonomy) chuẩn và loại bỏ (deduplicate) các entry tương tự nhau.","C":"Bổ sung (enrich) schema với các trường bổ sung để ghi nhận extraction metadata.","D":"Thêm few-shot examples minh họa cách xử lý cụm từ ghép (compound phrase), tiêu chí đề cập rõ ràng (explicit mention), và mức độ chi tiết (granularity) phù hợp cho từng entry."}},"38":{"q":"Pipeline của bạn sử dụng một tool tên là extract_metadata với JSON schema cho thông tin chi tiết bài báo (paper details). Bạn cũng đã định nghĩa các tool lookup_citations và verify_doi để bổ sung thông tin (enrichment). Trong quá trình testing, bạn nhận thấy rằng khi user đưa ra các yêu cầu như \"extract the metadata and tell me how cited it is,\" Claude đôi khi gọi lookup_citations trước, dẫn đến lỗi vì tool này cần DOI mà lẽ ra phải do extract_metadata cung cấp. Đâu là cách hiệu quả nhất để đảm bảo việc trích xuất metadata có cấu trúc (structured metadata extraction) luôn diễn ra trước?","o":{"A":"Đặt tool_choice thành (\"type\": \"tool\", \"name\": \"extract_metadata\") và xử lý các yêu cầu enrichment ở các turn tiếp theo sau khi nhận được metadata đã trích xuất.","B":"Đặt tool_choice thành \"any\" để buộc Claude phải dùng một tool, kết hợp với hướng dẫn trong system prompt ưu tiên extract_metadata.","C":"Đặt tool_choice thành (\"type\": \"tool\", \"name\": \"extract_metadata\") cho mọi lệnh gọi API trong pipeline, đảm bảo Claude luôn trích xuất metadata trước khi bất kỳ enrichment nào có thể diễn ra.","D":"Đặt tool_choice thành \"auto\" và sắp xếp lại các định nghĩa tool để extract_metadata xuất hiện đầu tiên trong mảng tools, vì Claude ưu tiên các tool được liệt kê trước."}},"39":{"q":"Hệ thống của bạn đã vận hành với 100% human review trong 3 tháng. Phân tích cho thấy các lượt extraction có model confidence >90% đạt độ chính xác 97% overall. Để giảm khối lượng công việc cho reviewer, bạn dự định tự động hóa các lượt extraction có confidence cao. Trước khi triển khai, bước validation nào là quan trọng nhất cần thực hiện?","o":{"A":"Xác minh rằng độ chính xác 97% đáp ứng yêu cầu của tất cả các hệ thống downstream tiêu thụ dữ liệu đã trích xuất.","B":"Phân tích độ chính xác theo loại tài liệu (document type) và theo trường (field) để xác minh rằng các trích xuất có độ tin cậy (confidence) cao hoạt động nhất quán trên tất cả các phân khúc (segment), chứ không chỉ ở mức tổng hợp (aggregate).","C":"So sánh độ chính xác ở các ngưỡng confidence khác nhau (85%, 90%, 95%) để tìm ra điểm cắt (cutoff) tối ưu, tối đa hóa mức độ tự động hóa (automation) trong khi giảm thiểu lỗi.","D":"Chạy thử nghiệm (pilot) trong hai tuần, định tuyến (route) 25% các trích xuất có confidence cao trực tiếp đến các hệ thống downstream, và theo dõi các báo cáo lỗi."}},"40":{"q":"Hệ thống extraction của bạn sử dụng tool_use với một JSON schema gồm 12 field và các mô tả (description) chi tiết, tổng cộng khoảng 2.500 token cho toàn bộ tool definition. Xử lý các tài liệu dưới 150K token cho độ chính xác 98%. Với các tài liệu trong khoảng 175-190K token, độ chính xác giảm xuống còn 71%, với thông tin ở một phần ba cuối tài liệu (final third) liên tục bị bỏ sót. Context window của model là 200K token. Nguyên nhân nhiều khả năng nhất là gì?","o":{"A":"Các định nghĩa tool tiêu tốn token trong input context. Kết hợp với system prompt và nội dung tài liệu, tổng số token tiến gần đến giới hạn context (context limit), làm giảm chất lượng xử lý ở phần cuối tài liệu.","B":"Các tài liệu rất dài vượt quá khả năng tập trung chú ý (attention span) hiệu quả của model bất kể context limit, khiến độ chính xác giảm đối với nội dung nằm xa hơn so với hướng dẫn trong prompt.","C":"Model phân bổ sự chú ý (attention) tỷ lệ theo chiều dài input, khiến các trường chỉ được nhắc đến một lần gần cuối tài liệu nhận được sự tập trung xử lý không đủ.","D":"Các schema có hơn 8-10 trường làm tăng độ phức tạp khi ra quyết định (decision complexity) trong quá trình sinh tham số (parameter generation), làm giảm độ chính xác trích xuất bất kể độ dài tài liệu."}},"41":{"q":"Pipeline extraction của bạn xử lý hóa đơn và trích xuất các line item, subtotal, số tiền thuế, và grand total. Trong quá trình evaluation, bạn phát hiện rằng trong 18% số lần extraction, tổng các line item amount được trích xuất không khớp với grand total được trích xuất—đôi khi do lỗi OCR trong tài liệu gốc, đôi khi do lỗi extraction của model. Các hệ thống kế toán ở downstream từ chối các bản ghi có tổng số không khớp. Đâu là cách tiếp cận hiệu quả nhất để cải thiện độ tin cậy (reliability) của extraction?","o":{"A":"Thêm một trường \"calculated total\" để model tính tổng các line items đã trích xuất, cùng với một trường \"stated_total\". Gắn cờ (flag) các bản ghi để con người xem xét khi hai giá trị này khác nhau.","B":"Trích xuất line items và totals một cách độc lập, sau đó dùng một model xác thực riêng để đối chiếu các sai lệch bằng cách xác định giá trị nào được trích xuất có khả năng đúng nhất.","C":"Thêm các few-shot examples minh họa các hóa đơn mà tổng các line items được trích xuất khớp chính xác với stated total, nhằm khuyến khích model tạo ra các kết quả trích xuất nhất quán về mặt toán học.","D":"Triển khai bước post-processing tự động điều chỉnh số tiền của các line items theo tỷ lệ khi tổng của chúng không khớp với stated total."}},"42":{"q":"Hệ thống extraction của bạn xử lý hai loại tài liệu: báo cáo hàng tháng tiêu chuẩn (được archive sau khi xử lý) và báo cáo ngoại lệ khẩn cấp (phải kích hoạt cảnh báo business trong vòng 30 phút kể từ khi nhận được). Cả hai đều sử dụng cùng một JSON schema. Bạn muốn giảm thiểu chi phí API trong khi vẫn đáp ứng yêu cầu về latency. Bạn nên thiết kế kiến trúc cho processing pipeline như thế nào?","o":{"A":"Gửi tất cả tài liệu đến Batch API với custom_id để theo dõi. Khi kết quả trả về, xử lý ngay các tài liệu khẩn cấp và kích hoạt cảnh báo trễ cho các trường hợp ngoại lệ.","B":"Gửi tất cả tài liệu đến Messages API theo thời gian thực (real-time) để đảm bảo độ trễ xử lý nhất quán giữa các loại tài liệu.","C":"Đưa tất cả tài liệu vào hàng đợi và gửi theo batch mỗi giờ, gắn cờ các tài liệu khẩn cấp để xử lý nhanh khi kết quả batch trả về.","D":"Định tuyến các báo cáo thông thường đến Batch API để tiết kiệm 50% chi phí, và định tuyến các báo cáo ngoại lệ khẩn cấp đến Messages API theo thời gian thực (real-time)."}},"43":{"q":"Pipeline extraction nhận các tài liệu thuộc nhiều loại khác nhau—một số là hóa đơn, một số là hợp đồng, và một số là biên lai. Bạn đã định nghĩa các extraction tool riêng biệt, mỗi tool có schema riêng phù hợp với loại tài liệu. Trong quá trình testing, bạn quan sát thấy rằng với tool_choice: \"auto\", Claude đôi khi trả về văn bản hội thoại (conversational text) thay vì gọi một extraction tool, gây ra lỗi parsing ở downstream. Bạn cần đảm bảo có structured output mà không biết trước loại tài liệu. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Hợp nhất tất cả các loại tài liệu vào một tool trích xuất duy nhất có unified schema, và force tool đó.","B":"Giữ tool_choice: \"auto\" cùng với các hướng dẫn trong system prompt yêu cầu phải sử dụng tool.","C":"Đặt tool_choice: \"any\" với tất cả các tool trích xuất đã được định nghĩa.","D":"Thêm một lệnh gọi phân loại sơ bộ (preliminary classification call), sau đó thực hiện lệnh gọi thứ hai với tool_choice được force vào tool trích xuất đã xác định."}},"44":{"q":"Monitoring cho thấy 12% số lần extraction fail Pydantic validation với các lỗi cụ thể như \"expected float for quantity, got '2 to 3'\". Việc retry các request này mà không thay đổi gì vẫn tiếp tục tạo ra lỗi. Đâu là cách tiếp cận hiệu quả nhất để khắc phục các lỗi validation này?","o":{"A":"Đặt temperature bằng 0 để loại bỏ sự biến thiên trong output và đảm bảo định dạng nhất quán.","B":"Gửi một request tiếp theo kèm theo lỗi validation, yêu cầu model sửa lại output của mình.","C":"Tiền xử lý (pre-process) các tài liệu nguồn để chuẩn hóa các định dạng gây vấn đề trước khi gửi đi trích xuất.","D":"Triển khai một pipeline phụ sử dụng model ở tier lớn hơn để xử lý lại các tài liệu không vượt qua validation."}},"45":{"q":"Sau ba tháng với các session hàng tuần, conversation history của bạn đã tăng lên đến 85,000 tokens. Khi người dùng hỏi \"Chúng ta đã kết luận gì về chủ đề sự cô lập?\", assistant đưa ra phân tích văn học chung chung thay vì tham chiếu đến những nhận định cụ thể của nhóm từ các session trước đó. Các buổi thảo luận thường được xây dựng dựa trên kết luận của các buổi họp trước, vì vậy việc duy trì narrative context là rất quan trọng. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Thêm các XML tags có cấu trúc để đánh dấu các kết luận thảo luận quan trọng xuyên suốt lịch sử cuộc trò chuyện.","B":"Sử dụng semantic embedding để lập chỉ mục toàn bộ lịch sử cuộc trò chuyện và chỉ truy xuất (retrieve) các trao đổi trước đó có liên quan cho mỗi câu hỏi của user, thay thế định dạng cuộc trò chuyện tuyến tính bằng các đoạn được truy xuất.","C":"Triển khai rolling window truncation để chỉ giữ lại 25.000 tokens gần nhất.","D":"Triển khai tóm tắt dần (progressive summarization), trong đó các khối hội thoại cũ hơn được thay thế bằng các bản tóm tắt ngắn gọn trích xuất rõ ràng các kết luận chính, quyết định và các chủ đề lặp lại, đồng thời giữ nguyên văn (verbatim) các trao đổi gần đây."}},"46":{"q":"Sau một session kéo dài 40 phút giúp lên kế hoạch cho một bữa tiệc tối, cuộc hội thoại đã tăng lên đến 78,000 tokens. Lịch sử hội thoại bao gồm: (1) người dùng đề cập rằng một vị khách bị dị ứng nghiêm trọng với shellfish, (2) các số đo để scale công thức nấu ăn cho 8 phần ăn, (3) lời làm rõ của người dùng rằng \"bơ ở nhiệt độ phòng\" nghĩa là 68°F trong nhà bếp của họ, và (4) các trao đổi qua lại chung chung về thời gian dùng bữa và cách trình bày món ăn. Bạn cần triển khai context management trước khi đạt đến giới hạn của context window. Cách tiếp cận nào cân bằng tốt nhất giữa việc bảo toàn thông tin và việc giảm token?","o":{"A":"Tóm tắt toàn bộ lịch sử cuộc trò chuyện thành một bản tóm tắt ngắn gọn nắm bắt các chủ đề chính đã thảo luận, sau đó nối thêm các tin nhắn mới về sau.","B":"Triển khai một sliding window chỉ giữ lại 20.000 tokens gần nhất, dựa vào việc user tự nhắc lại thông tin quan trọng khi cần thiết.","C":"Lưu trữ toàn bộ cuộc trò chuyện ở bên ngoài và sử dụng semantic search để truy xuất các phần liên quan cho mỗi turn, chỉ nạp các đoạn khớp vào context.","D":"Trích xuất dữ liệu có cấu trúc quan trọng (dị ứng, số khẩu phần, các thuật ngữ do user định nghĩa) vào một phần tham chiếu (reference section) gọn nhẹ, tóm tắt phần thảo luận chung, và giữ nguyên văn (verbatim) các trao đổi gần đây."}},"47":{"q":"Bạn đang triển khai một tính năng cho phép người dùng tinh chỉnh (refine) sở thích playlist của họ qua nhiều turn hội thoại. Sau khi deploy, bạn nhận thấy các phản hồi của Claude không phản ánh những gì đã được nói trước đó trong cùng cuộc hội thoại—ví dụ, người dùng nói rằng họ thích nhạc jazz, nhưng hai tin nhắn sau đó Claude lại hỏi họ thích thể loại nhạc nào. Nguyên nhân nào có khả năng xảy ra nhất?","o":{"A":"Context window của model đã bị vượt quá do độ dài của cuộc trò chuyện.","B":"Claude API yêu cầu một tham số session_id mà bạn chưa cấu hình.","C":"Claude yêu cầu kết nối đến một vector database để duy trì bộ nhớ cuộc trò chuyện.","D":"Ứng dụng của bạn không đưa các tin nhắn trước đó vào mảng messages."}},"48":{"q":"Trợ lý huấn luyện thể hình (fitness coaching assistant) của bạn sử dụng một system prompt với logic điều kiện chi tiết: \"Nếu người dùng đề cập rằng họ là người mới bắt đầu, hãy cung cấp hướng dẫn form từng bước. Nếu họ dùng thuật ngữ 'progressive overload' hoặc 'superset', hãy trả lời ngắn gọn. Nếu họ hỏi về tiền sử chấn thương, luôn khuyên họ tham khảo ý kiến bác sĩ.\" Trong quá trình evaluation, bạn nhận thấy assistant xử lý đúng các trường hợp người dùng khai báo rõ ràng trình độ chuyên môn của mình, nhưng gặp khó khăn khi người dùng không nêu rõ trình độ—thường mặc định đưa ra các phản hồi quá chi tiết bất kể các contextual cue như thuật ngữ kỹ thuật. Thay đổi nào đối với system prompt sẽ giải quyết trực tiếp nhất tình trạng không nhận biết được các tín hiệu ngầm (implicit) về trình độ chuyên môn này?","o":{"A":"Thay thế hầu hết các điều kiện (conditionals) bằng một nguyên tắc chung: \"Điều chỉnh mức độ chi tiết của giải thích cho phù hợp với trình độ chuyên môn của user, phản ánh theo thuật ngữ mà họ sử dụng.\" Chỉ giữ lại điều kiện quan trọng về an toàn liên quan đến việc tham vấn (consultations).","B":"Thêm nhiều nhánh điều kiện hơn để bao quát các tín hiệu về trình độ chuyên môn khác, chẳng hạn như \"Nếu user đề cập đến các rep ranges cụ thể hoặc hỏi về periodization, coi là người có trình độ nâng cao (advanced).\"","C":"Triển khai một bước thu thập thông tin (intake) trước khi trò chuyện, yêu cầu user tự đánh giá mức độ kinh nghiệm của họ, sau đó chèn đánh giá đó vào system prompt như context cho tất cả các phản hồi tiếp theo.","D":"Thêm một hướng dẫn rõ ràng để model đặt một câu hỏi làm rõ (clarifying question) về mức độ kinh nghiệm bất cứ khi nào trình độ chuyên môn của user không rõ ràng ngay từ tin nhắn đầu tiên của họ."}},"49":{"q":"Trong quá trình testing ban đầu, bạn nhận thấy Claude dường như không nhớ các từ vựng đã được đề cập trước đó trong cuộc hội thoại. Khi một học viên hỏi \"Bạn có thể kiểm tra tôi về những từ đó không?\", Claude trả lời như thể chưa có từ nào được thảo luận. Lời giải thích nào có khả năng đúng nhất?","o":{"A":"System prompt của bạn cần các hướng dẫn rõ ràng yêu cầu Claude ghi nhớ thông tin từ các turn trước đó.","B":"Bạn không đưa các tin nhắn trước đó vào mỗi API request — API này là stateless nên không tự lưu giữ lịch sử cuộc trò chuyện.","C":"Bạn cần bật tính năng lưu giữ cuộc trò chuyện (conversation persistence) bằng cách truyền một tham số session ID với mỗi lệnh gọi API.","D":"Context window của model đã đầy, khiến nội dung trò chuyện trước đó bị loại bỏ."}},"50":{"q":"Trợ lý lên kế hoạch cải tạo nhà của bạn sử dụng một system prompt định nghĩa persona của một nhà thầu chuyên nghiệp (expert contractor) với các hướng dẫn cụ thể: luôn hỏi về ngân sách, đề xuất các lựa chọn thay thế ở nhiều mức giá khác nhau, và xác nhận yêu cầu về thời gian (timeline). Trong quá trình testing, các phản hồi tuân theo các hướng dẫn này ở turn 1-4, nhưng đến turn 7, assistant lại đưa ra lời khuyên chung chung mà không hỏi về ngân sách hay thời gian. Toàn bộ cuộc hội thoại chỉ có 2,500 tokens. Nguyên nhân nào có khả năng xảy ra nhất?","o":{"A":"System prompts chỉ thiết lập hành vi ban đầu và không duy trì hiệu lực xuyên suốt tất cả các turn.","B":"System prompt chỉ được gửi cùng với API request đầu tiên.","C":"Các phản hồi tích lũy của assistant đang làm loãng mức độ ảnh hưởng của system prompt.","D":"Sự chú ý (attention) của model đối với các hướng dẫn trong system prompt tự nhiên yếu dần khi số turn tích lũy tăng lên."}},"51":{"q":"Người dùng phản ánh rằng trong các cuộc hội thoại kéo dài, AI mất dấu (loses track of) các chủ đề cụ thể, ví dụ, và sở thích mà họ đã đề cập trước đó trong session. Cách triển khai hiện tại của bạn sử dụng một sliding window chỉ giữ lại 25 cặp tin nhắn gần nhất để nằm trong giới hạn context. Đâu là cách tiếp cận hiệu quả nhất để duy trì nhận biết về nội dung hội thoại trước đó trong khi vẫn quản lý được kích thước context?","o":{"A":"Thay thế sliding window bằng một phương pháp lai (hybrid): tóm tắt các tin nhắn cũ hơn trong khi vẫn giữ nguyên văn (verbatim) các tin nhắn gần đây.","B":"Triển khai vector similarity search trên toàn bộ lịch sử cuộc trò chuyện, truy xuất các tin nhắn trước đó có liên quan cho mỗi câu hỏi của user.","C":"Tăng kích thước window lên 50 cặp tin nhắn để giữ lại nhiều lịch sử trò chuyện hơn trước khi truncation.","D":"Thêm một lệnh gọi API riêng ở mỗi turn để tóm tắt các tin nhắn bị loại bỏ, rồi chèn bản tóm tắt liên tục (running summary) này vào đầu cuộc trò chuyện."}},"52":{"q":"Người dùng thường xuyên gửi các yêu cầu mơ hồ (ambiguous) như \"đặt một địa điểm cho bữa tiệc\" mà không nêu rõ ngày, số lượng khách, hay ngân sách. Kết quả evaluation của bạn cho thấy assistant hỏi trung bình 4 câu hỏi trước khi thực hiện bất kỳ hành động nào, khiến 35% người dùng bỏ cuộc giữa chừng cuộc hội thoại. Tuy nhiên, khi bạn giảm số câu hỏi, đôi khi người dùng lại nhận được các đề xuất không phù hợp với sở thích của họ. Đâu là cách tiếp cận hiệu quả nhất để cải thiện sự đánh đổi (trade-off) này?","o":{"A":"Triển khai một biểu mẫu thu thập thông tin có cấu trúc, thu thập trước tất cả các tham số cần thiết (ngày, số lượng khách, ngân sách, loại địa điểm) trước khi assistant bắt đầu đưa ra bất kỳ đề xuất nào.","B":"Cấu hình assistant để tiếp tục với các giá trị mặc định hợp lý (địa điểm cỡ trung bình, cuối tuần tới, ngân sách vừa phải) mà không nêu rõ các giả định này, cho phép user điều chỉnh nếu kết quả không khớp với mong đợi.","C":"Hướng dẫn assistant nêu rõ các giả định dựa trên tình trạng cuộc trò chuyện, tiếp tục đưa ra đề xuất trong khi mời user điều chỉnh, và chỉ dành các câu hỏi làm rõ (clarifying questions) cho những hành động không thể đảo ngược (irreversible) như xác nhận đặt chỗ.","D":"Cấu hình assistant để gộp tất cả các câu hỏi làm rõ thành một câu hỏi tổng hợp duy nhất (ví dụ: \"Bạn đang cân nhắc ngày nào, số lượng khách bao nhiêu, và ngân sách ra sao?\") nhằm giảm tổng số câu hỏi."}},"53":{"q":"Trong quá trình QA testing, bạn nhận thấy Claude tuân theo các hướng dẫn trong system prompt một cách nhất quán ở 10-15 turn đầu tiên, nhưng đến turn 25-30, các phản hồi bắt đầu lệch hướng—sử dụng giọng điệu thân mật khi yêu cầu là trang trọng, thỉnh thoảng bỏ qua định dạng bắt buộc, hoặc cung cấp các loại thông tin mà hướng dẫn hạn chế. Độ dài cuộc hội thoại vẫn nằm hoàn toàn trong giới hạn context (thường khoảng 30,000 tokens trên tổng số 200,000 tokens khả dụng). Đâu là cách tiếp cận hiệu quả nhất để duy trì hành vi nhất quán trong suốt các cuộc hội thoại kéo dài?","o":{"A":"Chèn các tin nhắn với vai trò user (user-role messages) để củng cố các hướng dẫn quan trọng tại các điểm ngắt tự nhiên trong cuộc trò chuyện, đặc biệt là trước các yêu cầu phức tạp.","B":"Triển khai validation sau khi có phản hồi (post-response), tạo lại từng phản hồi cho đến khi nó tuân thủ các hướng dẫn đã chỉ định.","C":"Tự động bắt đầu một cuộc trò chuyện mới sau 20 turn, truyền một bản tóm tắt của context trước đó để duy trì tính liên tục.","D":"Chuyển các hướng dẫn về hành vi từ system prompt sang tin nhắn đầu tiên của user."}},"54":{"q":"Phân tích performance cho thấy context của bạn được cấu thành từ các kết quả RAG tích lũy từ tất cả các query trước đó, điều này đang chiếm chỗ (crowding out) của conversation history và gây ra suy giảm tính mạch lạc (coherence degradation) sau hơn 15 turn. Cách tiếp cận nào giải quyết tốt nhất vấn đề này?","o":{"A":"Triển khai semantic deduplication để xác định và loại bỏ thông tin trùng lặp trong các kết quả RAG tích lũy và các turn hội thoại.","B":"Triển khai một sliding window cho các kết quả RAG từ 2-3 truy vấn gần nhất, trong khi vẫn giữ nguyên lịch sử cuộc trò chuyện.","C":"Điều chỉnh ngân sách context (context budget) nghiêng về các kết quả RAG, đồng thời giảm phần phân bổ cho lịch sử cuộc trò chuyện.","D":"Nén tất cả các kết quả RAG thành một tài liệu tóm tắt hợp nhất, được cập nhật dần (incrementally) sau mỗi lần retrieval."}},"55":{"q":"Trợ lý khám phá âm nhạc của bạn cần duy trì nhất quán một giọng điệu nhiệt tình, giải thích lý do (reasoning) cho mỗi đề xuất, và đặt các câu hỏi làm rõ (clarifying questions) để hiểu rõ hơn sở thích của người dùng. Bạn muốn hành vi này được duy trì một cách đáng tin cậy xuyên suốt tất cả các tương tác với người dùng. Bạn nên định nghĩa các hướng dẫn hành vi (behavioral guidelines) này ở đâu?","o":{"A":"Trong tin nhắn đầu tiên của assistant, hướng dẫn Claude tuân theo các nguyên tắc này từ đó về sau.","B":"Được chèn vào đầu mỗi tin nhắn của user trước khi gửi đến API.","C":"Trong system prompt.","D":"Trong các biến môi trường (environment variables) mà ứng dụng của bạn truyền cho API client."}},"56":{"q":"Trong một cuộc hội thoại về theo dõi đơn hàng, hệ thống bên ngoài của bạn nhận được một webhook cho biết gói hàng của người dùng đã được gửi đi. Người dùng đang chat tích cực và có khả năng sẽ sớm gửi tin nhắn tiếp theo. Bạn muốn assistant kết hợp một cách tự nhiên thay đổi trạng thái này vào phản hồi tiếp theo của nó. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Gửi ngay một API request với thông tin cập nhật dưới dạng một tin nhắn user giả lập (synthetic), tạo ra một phản hồi assistant không được yêu cầu (unsolicited).","B":"Nối thông tin cập nhật trạng thái vào đầu tin nhắn user tiếp theo trước khi gọi API.","C":"Cấu hình assistant để gọi tool get_order_status vào đầu mỗi phản hồi.","D":"Thêm trạng thái vận chuyển hiện tại vào system prompt trước lệnh gọi API tiếp theo."}},"57":{"q":"Tin nhắn đầu tiên của một người dùng mới là \"Thiết lập nhạc tập trung cho tôi.\" Câu này có thể có nghĩa là cấu hình sở thích, tạo một playlist, hoặc phát nhạc ngay lập tức. Hệ thống của bạn hỗ trợ cả ba hành động này. Đâu là cách tiếp cận hiệu quả?","o":{"A":"Tạo một playlist \"Focus\" mới với các bài hát được tuyển chọn và thông báo cho user rằng nó đã sẵn sàng.","B":"Đặt một câu hỏi làm rõ duy nhất về loại hành động: phát ngay hay cấu hình để dùng sau.","C":"Phát ngay các bài hát tập trung (focus) phổ biến và để user điều chỉnh nếu cần.","D":"Bắt đầu cấu hình sở thích bằng cách hỏi về thể loại (genres), tempo, và nghệ sĩ mà họ thích cho việc tập trung (focus)."}},"58":{"q":"Người dùng phản ánh rằng các phản hồi có cảm giác lặp lại qua các turn—mỗi tin nhắn đều bắt đầu bằng các cụm từ như \"Certainly!\" hoặc \"I'd be happy to help!\" ngay cả khi cuộc hội thoại đã diễn ra rất sâu. Bạn muốn các phản hồi cảm thấy tự nhiên hơn, không có những câu mở đầu lặp lại này. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Triển khai post-processing để phát hiện và loại bỏ các cụm từ chào hỏi thông thường ở đầu phản hồi.","B":"Thêm các hướng dẫn trong system prompt chỉ định các cụm từ cần tránh, chẳng hạn như \"Không bao giờ bắt đầu phản hồi bằng 'Certainly' hoặc các từ khẳng định tương tự.\"","C":"Giảm tham số temperature để phần mở đầu phản hồi mang tính xác định (deterministic) hơn và ít biến thiên hơn.","D":"Nối thêm một tin nhắn assistant chưa hoàn chỉnh (partial) với một câu mở đầu phản hồi trực tiếp để model tiếp tục từ đó."}},"60":{"q":"Tool process refund của bạn trả về hai loại lỗi: lỗi kỹ thuật (\"503 Service Unavailable\", \"Connection timeout\") mang tính tạm thời (transient) (5% số lần gọi), và lỗi nghiệp vụ (business error) (\"Order exceeds 3 day return window\", \"item already refunded\") mang tính vĩnh viễn (permanent) (12% số lần gọi). Monitoring cho thấy agent lãng phí 3-4 turn để retry các business error vốn không bao giờ có thể thành công. Hiện tại, cả hai loại lỗi đều chỉ trả về một thông báo văn bản thuần túy cho Claude. Đâu là cách hiệu quả nhất để giảm thiểu các lần retry lãng phí trong khi vẫn cải thiện chất lượng phản hồi hướng đến khách hàng (customer-facing)?","o":{"A":"Thêm các few-shot examples minh họa cách phân biệt lỗi có thể thử lại (retriable) với lỗi không thể thử lại bằng cách phân tích (parse) nội dung thông báo lỗi.","B":"Thêm một tool check refund eligibility bắt buộc phải được gọi trước process refund để ngăn chặn việc vi phạm các quy tắc nghiệp vụ (business rule).","C":"Triển khai logic tự động retry ở cấp độ tool chỉ dành cho các lỗi kỹ thuật, còn các lỗi nghiệp vụ (business errors) được chuyển thẳng cho Claude mà không retry.","D":"Trả về các phản hồi lỗi có cấu trúc với retriable là false cho các lỗi nghiệp vụ, kèm theo một lời giải thích thân thiện với khách hàng để Claude sử dụng."}},"61":{"q":"Agent của bạn đã gọi lookup_order nhiều lần trong khi điều tra các yêu cầu trả hàng của một khách hàng. Mỗi phản hồi bao gồm hơn 40 trường dữ liệu (items, shipping details, payment info, v.v.), và các tool output này hiện chiếm phần lớn context của cuộc hội thoại. Khách hàng đề cập thêm hai đơn hàng nữa mà họ muốn thảo luận. Đâu là cách tiếp cận hiệu quả nhất trước khi thực hiện các lookup tiếp theo?","o":{"A":"Chuyển tất cả các phản hồi từ tool vào một vector database có lập chỉ mục ngữ nghĩa (semantic indexing), truy xuất các phần liên quan khi cuộc trò chuyện tiếp diễn.","B":"Chỉ trích xuất các trường liên quan đến việc trả hàng (items, ngày mua, return window, status) từ mỗi phản hồi đơn hàng hiện có, loại bỏ các chi tiết dài dòng.","C":"Để model tạo ra một bản tóm tắt bằng ngôn ngữ tự nhiên (natural language) về các chi tiết chính của mỗi đơn hàng, thay thế các phản hồi có cấu trúc bằng các mô tả văn xuôi (prose).","D":"Tiếp tục thực hiện các lookups bổ sung mà không sửa đổi context output hiện có của tool."}},"62":{"q":"Trong quá trình giải quyết một khiếu nại về thanh toán, agent của bạn lấy thành công thông tin khách hàng qua get_customer và chi tiết đơn hàng qua lookup_order, nhưng khi gọi process_refund, tool trả về lỗi timeout. Agent có đủ thông tin để giải thích các khoản phí và xác minh điều kiện được hoàn tiền, nhưng không thể thực sự xử lý việc hoàn tiền do backend gặp sự cố. Cách tiếp cận nào cân bằng tốt nhất giữa việc giải quyết ngay từ lần liên hệ đầu tiên (first-contact resolution) và việc xử lý lỗi phù hợp?","o":{"A":"Xác nhận rằng khoản hoàn tiền sẽ được xử lý và kết thúc cuộc hội thoại, vì hệ thống đã có đầy đủ thông tin cần thiết để tự động hoàn tất việc này","B":"Giải thích về việc thanh toán, xác nhận điều kiện được hoàn tiền, thừa nhận sự cố hệ thống đang ngăn cản việc xử lý ngay lập tức, và đề xuất chuyển lên (escalate) hoặc thử lại sau","C":"Chuyển ngay lập tức lên nhân viên hỗ trợ (human agent) vì hành động hoàn tiền không thể hoàn tất","D":"Triển khai cơ chế tự động thử lại (retry) với exponential backoff cho process_refund, giữ cuộc hội thoại mở cho đến khi khoản hoàn tiền được xử lý thành công"}},"63":{"q":"Agent của bạn đang xử lý một khiếu nại về thanh toán. Sau khi gọi get_customer và lookup_order, nó xác định rằng khiếu nại này liên quan đến một lỗi giá khuyến mãi cần có sự phê duyệt của quản lý—vượt quá mức thẩm quyền của agent. Quy trình làm việc nên xử lý việc leo thang (escalation) giữa chừng này như thế nào?","o":{"A":"Lưu trữ toàn bộ lịch sử cuộc hội thoại và phản hồi từ tool vào cơ sở dữ liệu, sau đó gọi escalate_to_human kèm theo một reference ID.","B":"Gọi escalate_to_human chỉ với tin nhắn gốc ban đầu của khách hàng.","C":"Vẫn cố gắng thực hiện hoàn tiền bằng process_refund, chỉ chuyển lên (escalate) nếu hệ thống từ chối giao dịch.","D":"Tổng hợp một bản bàn giao (handoff) có cấu trúc gồm thông tin khách hàng, thông tin đơn hàng, và vấn đề đã xác định được trước khi gọi escalate_to_human."}},"64":{"q":"Log sản xuất (production logs) cho thấy việc xử lý lỗi không nhất quán: khi lookup_order thất bại, agent đôi khi thử lại 5 lần trở lên (lãng phí khi order ID không tồn tại), đôi khi leo thang ngay lập tức (quá sớm đối với các sự cố mạng tạm thời), và đôi khi hỏi người dùng để làm rõ (không phù hợp khi vấn đề là lỗi phân quyền ở backend). Điều tra cho thấy MCP tool của bạn trả về các phản hồi lỗi đồng nhất: {\"isError\": true, \"content\": [{\"type\": \"text\", \"text\": \"Operation failed\"}]}. Agent không thể phân biệt giữa các loại lỗi. Cải tiến nào hiệu quả nhất?","o":{"A":"Cải thiện các phản hồi lỗi bằng metadata có cấu trúc: bao gồm errorCategory (transient/validation/permission), một boolean isRetryable, và một mô tả về nguyên nhân gây ra lỗi.","B":"Triển khai logic thử lại (retry) với exponential backoff trong MCP server của bạn cho tất cả các lỗi, chỉ trả kết quả về cho agent sau khi đã hết số lần thử lại.","C":"Thêm các ví dụ few-shot vào system prompt minh họa cách diễn giải các mẫu thông báo lỗi và chọn phản hồi phù hợp cho từng trường hợp.","D":"Tạo một MCP tool tên analyze_error để agent gọi sau bất kỳ lỗi nào, nhằm xác định loại lỗi (error category) và hành động được đề xuất."}},"65":{"q":"Một khách hàng nêu ra ba vấn đề riêng biệt trong một phiên làm việc: một yêu cầu hoàn tiền (turn 1-15), một câu hỏi về subscription (turn 16-30), và một yêu cầu cập nhật phương thức thanh toán (turn 31-45). Tại turn 48, khách hàng hỏi \"Chuyện gì đã xảy ra với khoản hoàn tiền của tôi?\" Cuộc hội thoại đang tiến gần đến giới hạn context. Chiến lược nào duy trì tốt nhất khả năng của agent trong việc giải quyết tất cả các vấn đề trong suốt phiên làm việc?","o":{"A":"Triển khai một context dạng sliding window chỉ giữ lại 30 turn gần nhất.","B":"Trích xuất và lưu trữ dữ liệu vấn đề có cấu trúc (order ID, số tiền, trạng thái) vào một lớp context riêng biệt.","C":"Dựa vào các MCP tool để lấy lại thông tin liên quan theo yêu cầu khi khách hàng đề cập đến các vấn đề trước đó.","D":"Tóm tắt các turn trước đó thành một mô tả dạng tường thuật, chỉ giữ nguyên toàn bộ lịch sử tin nhắn cho vấn đề đang xử lý."}},"66":{"q":"Tool update_user_profile của bạn nhận một user_id (bắt buộc) và một object fields_to_update (tùy chọn). Trong quá trình kiểm thử, Claude thường xuyên bỏ sót user_id hoặc truyền dữ liệu có cấu trúc không đúng. Điều gì là quan trọng nhất để giúp Claude hiểu được cần cung cấp giá trị tham số nào?","o":{"A":"Mô tả tham số rõ ràng giải thích định dạng mong đợi, chẳng hạn \"user_id : UUID of the user to update (required)\"","B":"Tên tham số dài dòng mã hóa gợi ý về định dạng, chẳng hạn user_id_string_uuid_format","C":"Các ràng buộc kiểu chặt chẽ trong JSON Schema đánh dấu user_id là required và định nghĩa fields_to_update là kiểu object","D":"Các phản hồi lỗi chi tiết giải thích lý do các giá trị tham số không hợp lệ bị từ chối"}},"67":{"q":"Giám sát production cho thấy tool search_catalog của bạn thất bại 12% số lần: 8% là do timeout mạng và sẽ thành công nếu thử lại ngay lập tức, trong khi 4% là lỗi cú pháp truy vấn (query syntax error) do các bộ lọc (filter) do người dùng cung cấp bị sai định dạng, và sẽ không bao giờ thành công dù thử lại bao nhiêu lần. Hiện tại, cả hai loại lỗi đều được trả về cho agent giống hệt nhau, khiến agent lãng phí lượt để thử lại các lỗi cú pháp và báo người dùng \"thử lại sau\" đối với các lỗi timeout. Bạn nên sửa đổi cách xử lý lỗi của tool này như thế nào?","o":{"A":"Áp dụng logic thử lại (retry) với exponential backoff một cách đồng nhất cho tất cả các lỗi, trả về một thông báo chung \"service temporarily unavailable\" sau khi đã hết số lần thử lại tối đa.","B":"Trả về tất cả các lỗi kèm theo một cờ boolean retryable và thông tin chi tiết về loại lỗi.","C":"Triển khai tự động thử lại (retry) với backoff cho các network timeout ngay bên trong tool; trả về ngay lập tức các lỗi cú pháp (syntax error) kèm thông tin chi tiết về việc xác thực tham số (parameter validation).","D":"Thêm các ví dụ few-shot vào system prompt của bạn minh họa cách phân biệt lỗi mạng (network error) với lỗi cú pháp (syntax error) và xử lý phù hợp cho từng trường hợp."}},"68":{"q":"Người dùng thường xuyên gửi các yêu cầu mơ hồ như \"đặt một venue cho buổi tiệc\" mà không nêu rõ ngày, số lượng khách, hay ngân sách. Đánh giá của bạn cho thấy assistant hỏi trung bình 4,2 câu hỏi làm rõ trước khi thực hiện bất kỳ hành động nào, khiến 35% người dùng bỏ cuộc giữa chừng cuộc hội thoại. Tuy nhiên, khi bạn giảm số câu hỏi, đôi khi người dùng nhận được các đề xuất không khớp với sở thích của họ. Cách tiếp cận nào hiệu quả nhất để cải thiện sự đánh đổi (trade-off) này?","o":{"A":"Hướng dẫn assistant nêu rõ các giả định (assumptions) dựa trên lịch sử hội thoại, tiếp tục đưa ra đề xuất trong khi mời người dùng chỉnh sửa nếu cần, và chỉ dành các câu hỏi làm rõ (clarifying question) cho những hành động không thể đảo ngược như xác nhận đặt chỗ (booking).","B":"Cấu hình assistant để tiếp tục với các giá trị mặc định hợp lý (địa điểm cỡ vừa, cuối tuần tới, ngân sách vừa phải) mà không nêu rõ các giả định này, cho phép người dùng chỉnh sửa nếu kết quả không đúng như kỳ vọng.","C":"Triển khai một biểu mẫu tiếp nhận (intake form) có cấu trúc thu thập trước tất cả các tham số cần thiết (ngày, số lượng khách, ngân sách, loại địa điểm) trước khi assistant bắt đầu đưa ra bất kỳ đề xuất nào.","D":"Cấu hình assistant để gộp tất cả các câu hỏi làm rõ thành một câu hỏi ghép duy nhất (ví dụ: \"Bạn đang cân nhắc ngày nào, số lượng khách bao nhiêu, và ngân sách ra sao?\") nhằm giảm tổng số turn hội thoại."}},"69":{"q":"Tool trích xuất tài liệu (document extraction) của bạn sử dụng các mô hình ML để trích xuất các trường trên hóa đơn (nhà cung cấp, số tiền, ngày tháng). Các mô hình trả về điểm tin cậy (confidence score, từ 0.0 đến 1.0) cho mỗi trường được trích xuất. Trong production, bạn quan sát thấy: (1) agent tiếp tục xử lý với các kết quả trích xuất có độ tin cậy thấp, và các kết quả này sai 23% số lần, và (2) agent yêu cầu con người xem xét (human review) một cách không cần thiết đối với 31% các trường hợp trích xuất mà thực ra là chính xác. Bạn nên tái cấu trúc đầu ra của tool này như thế nào?","o":{"A":"Trả về các field kèm theo confidence score thô của chúng, và thêm các ví dụ few-shot chi tiết vào system prompt minh họa cách diễn giải các khoảng confidence khác nhau và khi nào cần yêu cầu con người xem xét lại (human review).","B":"Tính toán một điểm chất lượng trích xuất (extraction quality score) tổng hợp trên tất cả các field và trả về kèm theo các giá trị đã trích xuất. Kèm theo một bản tóm tắt dạng văn bản mô tả độ tin cậy tổng thể của việc trích xuất.","C":"Trả về các field kèm confidence score, cùng với một boolean requires_review được tính toán dựa trên các ngưỡng confidence (confidence threshold) đã được kiểm chứng, cùng với một mảng review_reasons giải thích field nào đã kích hoạt việc xem xét lại.","D":"Trả về các field được sắp xếp thành các object verified và needs_verification dựa trên các ngưỡng confidence."}},"70":{"q":"Agent của bạn có một tool update_game_score nhận các tham số game_date (string), home_team (string), và away_team (string). Log production cho thấy các vấn đề lặp lại: agent sử dụng biệt danh (nickname) của đội thay vì tên chính thức, áp dụng định dạng ngày không nhất quán, và chọn sai trận đấu khi các đội có trận tái đấu (rematch) trong cùng mùa giải. Thay đổi nào đối với giao diện tool sẽ ngăn chặn hiệu quả các lỗi này?","o":{"A":"Thêm một tham số season để làm rõ các trận đấu lại (rematch), và thêm một cờ confirm_before_update để trả về thông tin chi tiết trận đấu đã được xác định (resolved) cho agent kiểm tra trước khi tỷ số được ghi nhận.","B":"Thêm các ví dụ chi tiết vào mô tả tool cho thấy định dạng ngày tháng cần thiết và danh sách đầy đủ tên các đội chính thức.","C":"Thêm các ràng buộc enum liệt kê tên đội hợp lệ cho cả hai tham số đội, và thêm một mẫu regex bắt buộc định dạng ISO 8601 cho tham số ngày.","D":"Thay thế ba tham số bằng một tham số duy nhất game_id và một tool tra cứu riêng biệt search_games trả về các game ID phù hợp."}},"71":{"q":"Tool phân bổ tài nguyên (resource allocation) của bạn trả về một thông báo xác nhận đơn giản sau khi việc cấp phát (provisioning) được yêu cầu. Người dùng thường xuyên phê duyệt việc cấp phát rồi ngay lập tức hỏi \"cái đó tốn bao nhiêu tiền?\" hoặc \"đó là dự án nào?\"—cho thấy họ đã xác nhận mà không hiểu rõ yêu cầu. Thay đổi thiết kế tool nào sẽ giải quyết vấn đề này hiệu quả nhất?","o":{"A":"Thêm một tham số user_acknowledged: boolean phải được đặt là true, kèm theo hướng dẫn để agent chỉ đặt giá trị này sau khi người dùng xác nhận rõ ràng rằng họ đã xem xét các chi tiết","B":"Triển khai một khoảng giữ (hold) 60 giây trước khi việc thực thi hoàn tất, cho phép người dùng có thời gian xem xét các phân bổ (allocation) đang chờ và hủy nếu cần","C":"Thêm một tham số detail_level với các tùy chọn \"minimal\" hoặc \"comprehensive\" để kiểm soát lượng context mà agent trình bày trong các xác nhận","D":"Trả về dữ liệu có cấu trúc bao gồm ước tính chi phí, dự án mục tiêu, thông số kỹ thuật của tài nguyên, và bản tóm tắt tác động trong phản hồi của tool"}},"72":{"q":"Lịch sử hội thoại của bạn bao gồm hai loại nội dung: các yếu tố cốt truyện lâu dài (persistent) (background nhân vật, cấu trúc cốt truyện, quy luật thế giới) cần phải luôn nhất quán, và các cuộc thảo luận brainstorm mở rộng phần lớn chỉ mang tính tạm thời (ephemeral). Sau hơn 40 turn, bạn đang chạm giới hạn context và người dùng phản ánh rằng assistant \"quên\" các đặc điểm nhân vật đã được thiết lập, phá vỡ tính nhất quán của câu chuyện (narrative consistency). Cách tiếp cận nào đảm bảo tốt nhất rằng các yếu tố cốt truyện lâu dài vẫn khả dụng đối với model trong khi vẫn lấy lại được không gian context?","o":{"A":"Tách các yếu tố cốt truyện lâu dài (persistent) thành một phần \"story bible\" được giữ lại ở đầu context, chỉ áp dụng việc cắt gọn (trimming) hoặc tóm tắt cho phần thảo luận brainstorming.","B":"Lưu trữ toàn bộ lịch sử vào một vector database và truy xuất các đoạn văn có ngữ nghĩa tương tự cho mỗi tin nhắn mới, thay thế lịch sử hội thoại bằng các chunk được truy xuất.","C":"Áp dụng cách tiếp cận sliding-window chỉ giữ lại 25 turn gần nhất, dựa vào việc model tự suy luận context trước đó từ luồng thảo luận gần đây.","D":"Tóm tắt toàn bộ lịch sử hội thoại thành một bản tóm lược (synopsis) cô đọng sau mỗi 20 turn, thay thế toàn bộ lịch sử để giải phóng token."}},"73":{"q":"Trợ lý hội thoại của bạn thường xuyên đưa ra nhiều câu hỏi làm rõ khi người dùng đưa ra các yêu cầu mơ hồ. Khi một người dùng hỏi \"Bạn có thể giúp tôi với báo cáo không?\", assistant trả lời: \"Tôi rất sẵn lòng giúp! Bạn có thể cho tôi biết: 1) Báo cáo nào? 2) Loại giúp đỡ nào—soạn thảo, xem xét, hay định dạng? 3) Deadline của bạn là khi nào?\" Dữ liệu phân tích người dùng cho thấy tỷ lệ bỏ cuộc hội thoại (abandonment rate) là 40% sau các phản hồi nhiều câu hỏi này. Cách hiệu quả nhất để giảm ma sát (friction) trong khi vẫn xử lý sự mơ hồ một cách phù hợp là gì?","o":{"A":"Giới hạn assistant chỉ đặt một câu hỏi làm rõ (clarifying question) mỗi turn, sử dụng lịch sử hội thoại để tích lũy câu trả lời qua nhiều lượt trao đổi thay vì yêu cầu tất cả ngay từ đầu.","B":"Chỉnh sửa system prompt để hướng dẫn assistant đưa ra các giả định hợp lý từ context sẵn có, nêu rõ các giả định đó, và đề nghị điều chỉnh nếu cách diễn giải sai.","C":"Thêm một bước tiền xử lý (preprocessing) sử dụng một model nhỏ hơn để phân loại mức độ mơ hồ của yêu cầu theo thang điểm 1-5, định tuyến các yêu cầu có độ mơ hồ cao đến một hộp thoại làm rõ (clarification dialog) và các yêu cầu có độ mơ hồ thấp trực tiếp đến assistant.","D":"Tạo một bảng tra cứu (lookup table) các mẫu yêu cầu phổ biến với các cách diễn giải mặc định được định trước, để assistant phản hồi theo các mặc định đó mà không nêu rõ các giả định đã đưa ra."}},"74":{"q":"Người dùng thường xuyên tinh chỉnh các tiêu chí tìm kiếm của họ giữa cuộc hội thoại. Bạn nhận thấy một khuôn mẫu: khi người dùng nói những câu như \"Thực ra, hãy tăng ngân sách lên $650K\" hoặc \"Tôi giờ muốn một căn condo thay vì một căn nhà\", assistant đôi khi vẫn tiếp tục tham chiếu đến các sở thích ban đầu trong các phản hồi sau đó—mặc dù các cập nhật rõ ràng đã có mặt trong lịch sử hội thoại. Mức sử dụng context chỉ ở 35% dung lượng. Giải pháp nào đảm bảo đáng tin cậy nhất rằng model sử dụng các sở thích hiện tại?","o":{"A":"Duy trì một state object có cấu trúc chứa các sở thích (preference) hiện tại, cập nhật nó khi có thay đổi, và đưa nó vào mỗi request.","B":"Triển khai việc cắt tỉa (pruning) hội thoại để loại bỏ các turn chứa sở thích đã lỗi thời, đảm bảo chỉ những sở thích hiện tại còn lại trong context.","C":"Đưa vào các ví dụ few-shot cho thấy assistant ghi nhận và áp dụng đúng các thay đổi về sở thích trong các phản hồi.","D":"Thêm các hướng dẫn vào system prompt nhấn mạnh rằng model nên luôn ưu tiên các sở thích được nêu gần đây nhất hơn các sở thích trước đó."}},"75":{"q":"Trợ lý gia sư hội thoại AI (conversational AI tutor) của bạn có một system prompt dài 2.800 token chứa phương pháp giảng dạy, hướng dẫn về persona, và các hướng dẫn chi tiết bằng văn bản để điều chỉnh cách giải thích theo các trình độ khác nhau. Kiểm thử người dùng cho thấy trong các cuộc hội thoại vượt quá 12 turn (khoảng 4.000 token lịch sử hội thoại), assistant ngày càng bỏ qua các hướng dẫn điều chỉnh theo trình độ, mặc định về các giải thích ở mức trung cấp bất kể trình độ mà người học đã nêu. Cách tiếp cận nào hiệu quả nhất để đảm bảo tuân thủ nhất quán các hướng dẫn này trong suốt các cuộc hội thoại kéo dài?","o":{"A":"Chèn một lời nhắc cô đọng về các yêu cầu về trình độ (proficiency) vào cuộc hội thoại dưới dạng một system message sau mỗi 4-5 turn.","B":"Thay thế các hướng dẫn về trình độ (proficiency) dài dòng bằng các ví dụ few-shot minh họa phản hồi phù hợp ở từng cấp độ trình độ, thể hiện rõ sự khác biệt cụ thể về từ vựng, độ phức tạp, và mức độ giải thích chi tiết.","C":"Tái cấu trúc system prompt để đặt các quy tắc điều chỉnh theo trình độ (proficiency-adaptation) vào một phần cuối được đánh dấu rõ ràng, ngay trước khi lịch sử hội thoại bắt đầu.","D":"Sau mỗi phản hồi của assistant, thực hiện một lệnh gọi API riêng để đánh giá xem mức độ khó có phù hợp với hồ sơ (profile) của người học hay không, tạo lại các phản hồi không phù hợp."}},"76":{"q":"Sau khi triển khai một system prompt đã cập nhật giúp cải thiện chất lượng phản hồi, những người dùng có các cuộc hội thoại nhiều phiên (multi-session) kéo dài nhiều tuần phản ánh rằng assistant giờ đây mâu thuẫn với các phát biểu trước đó của chính nó và có phong cách giao tiếp khác biệt rõ rệt. Người dùng mới không gặp phải các vấn đề này. Cách tiếp cận tốt nhất để giải quyết vấn đề này là gì?","o":{"A":"Tạo lại các bản tóm tắt của các cuộc hội thoại hiện có bằng prompt mới và thay thế lịch sử đã lưu để đồng bộ context trong quá khứ với hành vi hiện tại.","B":"Thêm một thông báo chuyển tiếp khi phiên (session) được tiếp tục, giải thích rằng assistant đã được cập nhật và hành vi có thể khác trước.","C":"Đánh phiên bản (version) cho system prompt và gắn mỗi cuộc hội thoại với phiên bản prompt mà nó đã bắt đầu, chỉ áp dụng các bản cập nhật cho các cuộc hội thoại mới.","D":"Thêm hướng dẫn vào system prompt mới, chỉ đạo assistant duy trì tính nhất quán với bất kỳ phát biểu nào trước đó trong lịch sử hội thoại."}},"77":{"q":"Coordinator agent đã được cấu hình AgentDefinitions cho cả bốn subagent chuyên biệt, mỗi subagent có description, prompt, và giới hạn tool phù hợp. Trong quá trình kiểm thử, bạn nhận thấy coordinator suy luận đúng về thời điểm nên ủy quyền (delegate)—nó tạo ra các thông điệp như \"Tôi sẽ yêu cầu web search agent tìm nguồn về chủ đề này\"—nhưng không có việc thực thi subagent nào xảy ra. Sau đó coordinator tiếp tục như thể việc ủy quyền đã diễn ra và tiếp tục với thông tin không đầy đủ. Log không cho thấy lỗi nào. Nguyên nhân nào có khả năng nhất?","o":{"A":"Cài đặt max_tokens của coordinator quá thấp, khiến lệnh gọi Task tool bị cắt ngắn trước khi tham số loại subagent có thể được chỉ định.","B":"Cấu hình allowedTools của coordinator không bao gồm \"Task\", vì vậy dù nó có thể suy luận về việc phân công (delegation), nó không thể gọi tool cần thiết để tạo (spawn) các subagent.","C":"Việc cô lập context của subagent (subagent context isolation) có nghĩa là các mô tả nhiệm vụ từ coordinator không tự động đến được các subagent; bạn cần cấu hình việc chuyển tiếp context (context forwarding) rõ ràng trong ClaudeAgentOptions.","D":"Các AgentDefinitions được cấu hình đúng, nhưng system prompt của coordinator không liệt kê rõ ràng các loại subagent hiện có, khiến model không biết rằng chúng có thể được gọi."}},"78":{"q":"Các đánh giá production cho thấy việc xử lý sự không chắc chắn (uncertainty) trong các báo cáo cuối cùng không nhất quán. Đôi khi các phát hiện mâu thuẫn từ các subagent được tổng hợp thành một tuyên bố tự tin duy nhất (làm mất đi sắc thái), trong khi những lúc khác báo cáo lại rào đón (hedge) quá mức với quá nhiều điều kiện (trở nên không hữu ích). Khi web search agent trả về \"các nhà phân tích ngành ước tính quy mô thị trường $50B (phương pháp luận khác nhau)\" và document analysis agent trả về \"nghiên cứu bình duyệt (peer-reviewed) ước tính $35B (±$7B, khoảng tin cậy 95%)\", coordinator hoặc chọn một cách tùy tiện hoặc đưa ra các tuyên bố mơ hồ như \"thị trường có thể là $35B-$50B tùy thuộc vào các yếu tố.\" Cách tiếp cận có hệ thống nào giải quyết tốt nhất vấn đề này?","o":{"A":"Triển khai một lớp hiệu chỉnh confidence (confidence calibration) để chuẩn hóa các biểu đạt về sự không chắc chắn của subagent thành các điểm xác suất (probability score) chuẩn hóa (0.0-1.0), sau đó tính trung bình có trọng số (weight-average) các phát hiện theo confidence đã được hiệu chỉnh.","B":"Hướng dẫn synthesis agent cấu trúc các báo cáo với các phần rõ ràng phân biệt giữa các phát hiện đã được xác lập vững chắc và các phát hiện còn gây tranh cãi, giữ nguyên cách mô tả nguồn gốc ban đầu và bối cảnh phương pháp luận.","C":"Cấu hình các subagent chỉ báo cáo các phát hiện đạt ngưỡng confidence cao, lọc bỏ thông tin không chắc chắn trước khi nó đến được coordinator.","D":"Thêm một subagent xác minh (verification) để đối chiếu chéo các phát hiện giữa các nguồn, chỉ chuyển đến synthesis những nhận định (claim) được xác nhận bởi ít nhất hai nguồn độc lập."}},"79":{"q":"Bạn đã cấu hình hệ thống sao cho cả bốn subagent đều có quyền truy cập vào toàn bộ 18 tool. Trong quá trình kiểm thử, các agent thường xuyên gọi các tool nằm ngoài chuyên môn của chúng—synthesis agent cố thực hiện tìm kiếm web, và report generator cố phân tích tài liệu. Nguyên nhân chính của hành vi lựa chọn tool kém này là gì?","o":{"A":"Việc phải lựa chọn giữa 18 tool thay vì chỉ 4-5 tool liên quan làm tăng độ phức tạp của việc ra quyết định vượt quá ngưỡng lựa chọn đáng tin cậy.","B":"Các mô tả vai trò (role) của agent trong system prompt của chúng mâu thuẫn với việc có quyền truy cập các tool nằm ngoài vai trò đó.","C":"Các định nghĩa tool (tool definition) chiếm quá nhiều không gian trong context window, không còn đủ chỗ cho nội dung nhiệm vụ.","D":"Coordinator không thể theo dõi được subagent nào có năng lực (capability) gì, dẫn đến việc định tuyến nhiệm vụ sai."}},"80":{"q":"Coordinator cung cấp các hướng dẫn chi tiết từng bước cho web search subagent, chỉ rõ các truy vấn tìm kiếm cụ thể, thứ tự ưu tiên nguồn, và bộ lọc theo ngày. Giám sát production cho thấy ba vấn đề: (1) subagent báo cáo \"kết quả không đủ\" thay vì thử các cách tiếp cận khác khi các tìm kiếm được chỉ định trước thất bại, (2) chất lượng nghiên cứu giảm đối với các chủ đề mới nổi không khớp với các khuôn mẫu dự kiến, và (3) subagent hiếm khi phát hiện ra các nguồn phụ (tangential) có giá trị. Cách hiệu quả nhất để cải thiện khả năng thích ứng của subagent là gì?","o":{"A":"Chỉ định các mục tiêu nghiên cứu và tiêu chí chất lượng (độ bao phủ, tính đa dạng nguồn, tính mới) thay vì các bước quy trình cụ thể, để subagent tự xác định chiến lược tìm kiếm của nó.","B":"Thêm các chỉ dẫn dự phòng (fallback) rõ ràng vào hướng dẫn chi tiết: \"Nếu các tìm kiếm được chỉ định cho ra ít hơn N kết quả, hãy thử các cách diễn đạt truy vấn khác trước khi báo cáo thất bại.\"","C":"Loại bỏ hoàn toàn các chi tiết về quy trình, giao việc bằng các mục tiêu đơn giản như \"nghiên cứu kỹ về X\" và dựa vào năng lực tổng quát của subagent.","D":"Triển khai một bước phân loại chủ đề, trong đó coordinator phân loại các yêu cầu thành \"được xác định rõ\" (well-defined) hoặc \"mang tính khám phá\" (exploratory) và sử dụng phong cách hướng dẫn khác nhau cho từng loại."}},"81":{"q":"Synthesis agent nhận các phát hiện đã được tóm tắt từ web search agent và document analysis agent, sau đó chuyển một bản tóm tắt hợp nhất cho report generator. Trong quá trình kiểm thử, bạn phát hiện các báo cáo được tạo ra đưa ra các tuyên bố sự việc mà không có trích dẫn phù hợp—report generator không thể quy kết các phát biểu về nguồn gốc ban đầu của chúng vì metadata đó đã bị mất trong các bước tóm tắt. Cách tiếp cận hiệu quả nhất để đảm bảo việc quy kết nguồn (source attribution) phù hợp trong các báo cáo cuối cùng là gì?","o":{"A":"Yêu cầu mỗi agent xuất ra dữ liệu có cấu trúc tách riêng phần tóm tắt nội dung khỏi metadata nguồn (URL, tên tài liệu, số trang).","B":"Yêu cầu report generator truy vấn lại web search agent để tìm lại nguồn cho các nhận định (claim) trong báo cáo cuối cùng.","C":"Bỏ qua việc tóm tắt và chuyển trực tiếp toàn bộ output thô từ web search và document analysis đến report generator.","D":"Hướng dẫn synthesis agent nhúng các tham chiếu nguồn (source reference) ngay trong văn bản tóm tắt của nó bằng một định dạng trích dẫn (citation) nhất quán."}},"82":{"q":"Một người dùng đang mở rộng hệ thống nghiên cứu vượt ra ngoài agent tìm kiếm web đơn lẻ ban đầu bằng cách thêm các nguồn dữ liệu chuyên biệt. Họ thêm một financial API agent trả về JSON có cấu trúc gồm doanh thu, biên lợi nhuận và tốc độ tăng trưởng; một news monitoring agent trả về các bản tóm tắt dạng văn xuôi về các diễn biến gần đây; và một patent analysis agent trả về các danh sách có cấu trúc về các lĩnh vực công nghệ. Synthesis agent kết hợp tất cả những thứ này thành các bản tóm tắt điều hành (executive briefings). Hiện tại, nó chuyển đổi mọi thứ thành các gạch đầu dòng, khiến các so sánh tài chính mất đi sự rõ ràng dạng bảng và các bản tóm tắt tin tức mất đi mạch tường thuật. Thay đổi nào sẽ cải thiện chất lượng của bản briefing nhiều nhất?","o":{"A":"Cập nhật synthesis agent để hiển thị mỗi loại nội dung một cách phù hợp—dữ liệu tài chính dưới dạng bảng, tin tức dưới dạng văn xuôi","B":"Chuẩn hóa tất cả output của subagent thành JSON với các trường claim, evidence, source, và confidence","C":"Thêm một lớp chuyển đổi định dạng giữa các subagent và synthesis, biến đổi tất cả output thành một dạng biểu diễn trung gian chung","D":"Chuẩn hóa tất cả output của subagent thành các đoạn tóm tắt văn xuôi kèm trích dẫn nội tuyến (inline citations)"}},"83":{"q":"Khi agent gọi lookup_order và nhận được chi tiết đơn hàng cho thấy sản phẩm đã được mua cách đây 45 ngày, agentic loop xác định như thế nào xem tiếp theo nên gọi process_refund hay escalate to human?","o":{"A":"Agent thực thi các bước còn lại trong một chuỗi tool đã được lên kế hoạch từ đầu request.","B":"Chi tiết đơn hàng được thêm vào cuộc hội thoại và model suy luận (reasons) về hành động nào cần thực hiện.","C":"Agent tuân theo một cây quyết định được cấu hình sẵn, ánh xạ các thuộc tính đơn hàng tới các lệnh gọi tool cụ thể.","D":"Lớp orchestration tự động định tuyến đến tool tiếp theo dựa trên trường status của đơn hàng."}},"84":{"q":"Agent xác minh danh tính khách hàng qua một quy trình nhiều bước trước khi đặt lại mật khẩu. Trong quá trình kiểm thử, bạn nhận thấy rằng sau khi khách hàng trả lời câu hỏi xác minh thứ ba, agent lại yêu cầu họ cung cấp tên một lần nữa, như thể trao đổi trước đó chưa từng xảy ra. Nguyên nhân nhiều khả năng nhất gây ra hành vi này là gì?","o":{"A":"Khả năng ghi nhớ của Claude mặc định chỉ giới hạn trong hai lượt hội thoại, cần cấu hình rõ ràng để mở rộng.","B":"Prompt thiếu chỉ dẫn yêu cầu Claude ghi nhớ thông tin qua nhiều lượt trao đổi.","C":"Tool xác minh đang xóa trạng thái nội bộ của agent sau mỗi bước kiểm định thành công.","D":"Lịch sử hội thoại không được truyền vào trong các API request tiếp theo."}},"85":{"q":"Khi triển khai tool lookup_order MCP của bạn, backend đôi khi trả về lỗi (ví dụ: \"Order not found\" hoặc các lỗi database tạm thời). Đâu là pattern đúng để truyền đạt các lỗi này trở lại cho agent?","o":{"A":"Ghi log lỗi phía server và trả về một kết quả rỗng để tránh gây nhầm lẫn cho model","B":"Ném ra một exception từ tool handler để agent framework có thể bắt và ghi log lại","C":"Trả về thông báo lỗi trong nội dung kết quả của tool với cờ isError được đặt thành true","D":"Trả về một phản hồi thành công kèm trường \"status\" cho biết loại lỗi"}},"86":{"q":"Evaluation cho thấy độ chính xác extraction đạt 94% trên các bản ghi cuộc họp (meeting transcripts) ngắn (<30 phút) nhưng chỉ đạt 68% trên các bản ghi dài hơn (>60 phút), nơi các cuộc thảo luận lan man và thông tin quan trọng bị rải rác khắp nơi. Các bản ghi ở cả hai độ dài đều nằm trong context window của model. Pattern nào cải thiện độ chính xác hiệu quả nhất đối với các tài liệu dài và phức tạp?","o":{"A":"Thêm các ví dụ few-shot minh họa cách trích xuất chính xác từ các cuộc họp dài với thông tin rải rác.","B":"Chia các bản ghi (transcript) dài thành từng đoạn (chunk), trích xuất riêng từ mỗi đoạn, sau đó gộp lại và loại bỏ trùng lặp.","C":"Nâng cấp lên một model có năng lực cao hơn cho tác vụ trích xuất,","D":"Thêm một bước tiền trích xuất, trong đó model tóm tắt các nội dung thảo luận và kết luận chính trước khi thực hiện trích xuất có cấu trúc."}},"87":{"q":"Hệ thống của bạn đã chạy được 3 tuần và những người review là con người đã sửa 847 lượt extraction. Phân tích cho thấy một pattern lặp lại: khi công thức nấu ăn sử dụng các đơn vị đo không chính thức như \"a handful\" hoặc \"a splash\", model hoặc là bịa ra các số lượng cụ thể hoặc để trống các trường—chiếm 23% tổng số lượt sửa. Bạn nên sử dụng phản hồi này như thế nào để cải thiện độ chính xác của extraction?","o":{"A":"Cập nhật JSON schema của bạn để thêm một trường enum \"measurement_type\" (precise/informal).","B":"Thêm các ví dụ few-shot vào prompt của bạn minh họa cách xử lý đúng các số đo không chính thức (informal measurements)—trích xuất nguyên văn thay vì chuyển đổi hoặc bỏ qua chúng.","C":"Triển khai một lớp hậu xử lý (post-processing) sử dụng khớp mẫu (pattern matching) để phát hiện các cụm từ đo lường không chính thức trong văn bản nguồn và tự động điền giá trị khi kết quả trích xuất trống.","D":"Fine-tune model trên 847 kết quả trích xuất đã được sửa."}},"88":{"q":"Giám sát production cho thấy các truy vấn tiếp nối (follow-up queries) như \"summarize what we learned about market trends\" liên tục mất hơn 40 giây. Điều tra cho thấy coordinator sinh ra (spawn) synthesis subagent cho mỗi yêu cầu tóm tắt, truyền vào hơn 80K token các phát hiện đã tích lũy được. Coordinator đã có sẵn các phát hiện này trong context của nó từ việc điều phối quá trình nghiên cứu. Đâu là cách hiệu quả nhất để cải thiện thời gian phản hồi cho các bản tóm tắt tiếp nối này?","o":{"A":"Bật prompt caching trên synthesis subagent để giảm chi phí phát sinh do phải truyền lặp lại cùng các kết quả nghiên cứu.","B":"Để coordinator tự xử lý trực tiếp các yêu cầu tóm tắt đơn giản bằng context hiện có của nó, chỉ dùng việc spawn subagent cho các phân tích phức tạp","C":"Spawn synthesis subagent với context được rút gọn và để nó yêu cầu các kết quả cụ thể từ coordinator khi cần (on-demand).","D":"Tạo trước và cache các bản tóm tắt ở nhiều mức độ chi tiết mỗi khi có kết quả nghiên cứu mới tích lũy."}},"89":{"q":"Document analysis agent có một tool duy nhất là analyze_document nhận vào một document và một tham số instruction dạng văn bản tự do (free-text). Trong quá trình evaluation, các yêu cầu như \"extract the key financial metrics\" thường trả về các bản tóm tắt tường thuật, trong khi \"summarize the methodology\" đôi khi lại trả về các bảng dữ liệu thô. Synthesis agent báo cáo rằng 35% kết quả phân tích cần phải yêu cầu lại (re-request) với các instruction đã được làm rõ. Đâu là cách hiệu quả nhất để cải thiện độ tin cậy?","o":{"A":"Nâng cao mô tả tool bằng các ví dụ chi tiết cho thấy các cách diễn đạt chỉ dẫn khác nhau nên ánh xạ tới các định dạng đầu ra khác nhau như thế nào","B":"Giữ nguyên một tool chung nhưng thêm một tham số enum analysis_type yêu cầu lựa chọn rõ ràng giữa các chế độ extraction, summarization, và verification","C":"Tách tool chung thành các tool chuyên biệt theo mục đích - extract_data_points, summarize_content, verify_claim_against_source - mỗi tool có hợp đồng input/output được định nghĩa rõ","D":"Để coordinator phân loại trước mỗi yêu cầu phân tích trước khi truyền chỉ dẫn cho document analysis agent"}},"90":{"q":"Hệ thống định tuyến các tài liệu có độ tin cậy extraction (extraction confidence) dưới 85% sang review bởi con người. Một cuộc audit hàng quý cho thấy 12% các extraction có độ tin cậy cao (>85%) cũng chứa lỗi—các trường hợp mà model tìm ra các giá trị nghe có vẻ hợp lý nhưng không chính xác. Nguồn gốc lỗi rất đa dạng: các bảng so sánh hiển thị thông số kỹ thuật của đối thủ cạnh tranh, các phụ lục tham chiếu đến các biến thể sản phẩm khác nhau, và cách diễn đạt mơ hồ mà model hiểu sai. Bạn cần một chiến lược bền vững để phát hiện các lỗi có độ tin cậy cao này và đo lường xem các cải tiến có làm giảm tỷ lệ lỗi theo thời gian hay không. Cách tiếp cận nào là hiệu quả nhất?","o":{"A":"Triển khai các quy tắc heuristic đánh dấu các tài liệu chứa bảng so sánh hoặc phụ lục để đưa vào rà soát, bất kể điểm confidence.","B":"Triển khai lấy mẫu ngẫu nhiên phân tầng (stratified random sampling), rà soát một tỷ lệ phần trăm cố định các kết quả trích xuất có confidence cao hằng tuần, giúp đo lường tỷ lệ lỗi và phát hiện các mẫu mới.","C":"Thêm một bước xác minh, trích xuất lại từ mỗi tài liệu có confidence cao, đánh dấu các trường hợp mà hai lần trích xuất cho kết quả khác nhau.","D":"Hạ ngưỡng confidence từ 85% xuống 70%, chuyển một khối lượng lớn hơn các kết quả trích xuất sang rà soát thủ công."}},"91":{"q":"Extraction của bạn sử dụng tool use với một JSON schema trong đó property_type được định nghĩa là một enum: ['house', 'apartment', \"condo\", \"townhouse\"]. Sau khi deploy, 8% các extraction bị fail schema validation. Điều tra cho thấy các listing đề cập đến nhiều loại bất động sản ít phổ biến—\"studio\", \"loft\", \"duplex\", \"mobile home\", \"tiny house\", \"converted warehouse\"—và các loại mới tiếp tục xuất hiện đều đặn. Đâu là giải pháp dài hạn hiệu quả nhất?","o":{"A":"Thêm một giá trị \"other\" vào enum của bạn, kèm một trường string riêng property_type_detail để ghi chi tiết cụ thể khi \"other\" được chọn.","B":"Đổi property_type từ enum thành một chuỗi tự do (free-form string) và triển khai một bước chuẩn hóa (normalization) trong hậu xử lý.","C":"Thêm các ví dụ few-shot vào prompt của bạn minh họa cách ánh xạ các loại property không mong đợi tới giá trị enum hiện có gần nhất.","D":"Liên tục mở rộng enum để bao gồm các loại property mới được quan sát và thêm cơ chế giám sát cho các trường hợp biên phát sinh thêm."}},"92":{"q":"Hệ thống extraction của bạn phân tích các mô tả sản phẩm thương mại điện tử để trích xuất các thông số kỹ thuật như kích thước, trọng lượng và chất liệu thành JSON. Mặc dù đã có một schema được định nghĩa rõ ràng, model vẫn trích xuất trường \"materials\" một cách không nhất quán—đôi khi trả về \"cotton blend\", lúc khác lại là \"Cotton/Polyester mix\", và thỉnh thoảng bỏ qua trường này ngay cả khi thông tin về chất liệu rõ ràng có trong nguồn. Đâu là cách hiệu quả nhất để cải thiện tính nhất quán của extraction?","o":{"A":"Đặt temperature bằng 0 để loại bỏ tính ngẫu nhiên và đảm bảo đầu ra tất định (deterministic)","B":"Chuyển sang một model có năng lực cao hơn vì việc trích xuất không nhất quán cho thấy năng lực model chưa đủ","C":"Đặt trường \"materials\" là bắt buộc thay vì tùy chọn trong schema để buộc model luôn phải trích xuất một giá trị","D":"Thêm các ví dụ few-shot cho thấy 2-3 cặp input-output hoàn chỉnh với các định dạng mô tả vật liệu đã được chuẩn hóa"}},"93":{"q":"Các tài liệu đến liên tục trong giờ làm việc và cần được trích xuất dữ liệu có cấu trúc. Để giảm chi phí, bạn muốn sử dụng Message Batches API (giảm giá 50%, cửa sổ xử lý lên đến 24 giờ). SLA của bạn quy định rằng kết quả extraction phải sẵn sàng trong vòng 30 giờ kể từ khi tài liệu đến với độ tin cậy 99.9%. Chiến lược batching nào là phù hợp nhất?","o":{"A":"Gửi các batch mỗi 4 giờ, chứa các tài liệu trong khoảng thời gian đó","B":"Gửi các batch mỗi 6 giờ, chứa các tài liệu trong khoảng thời gian đó","C":"Gửi một batch duy nhất vào cuối ngày, chứa tất cả tài liệu trong ngày đó","D":"Sử dụng real-time API cho tất cả tài liệu thay vì xử lý theo batch"}},"94":{"q":"Pipeline extraction của bạn xử lý thực đơn nhà hàng và phải xuất ra JSON có cấu trúc với các trường cho tên món ăn, mô tả, giá cả và các nhãn chế độ ăn (dietary tags). Một số thực đơn sử dụng định dạng không nhất quán—giá tiền là \"$12\" so với \"12.00\", thông tin chế độ ăn dưới dạng biểu tượng (icon) so với văn bản. Đâu là cách tiếp cận đáng tin cậy nhất?","o":{"A":"Trích xuất dữ liệu nguyên trạng và chuẩn hóa định dạng trong mã hậu xử lý sau khi Claude trả về kết quả.","B":"Định nghĩa một output schema chặt chẽ và đưa các quy tắc chuẩn hóa định dạng vào trong prompt của bạn.","C":"Sử dụng các lệnh gọi trích xuất riêng biệt cho từng trường để đảm bảo xử lý nhất quán cho mỗi loại.","D":"Yêu cầu nhiều lần trích xuất cho mỗi tài liệu và chọn ra định dạng xuất hiện phổ biến nhất."}},"95":{"q":"Hệ thống của bạn trích xuất metadata sự kiện (ngày, địa điểm, người tổ chức, số lượng người tham dự) từ các bài báo tin tức bằng một JSON schema với tất cả các trường đều là nullable. Trong quá trình evaluation, bạn quan sát thấy model thường xuyên tạo ra các giá trị nghe có vẻ hợp lý nhưng không chính xác cho các trường không được đề cập trong bài báo—ví dụ, xuất ra \"500\" cho attendee_count trong khi nguồn không chứa thông tin về số người tham dự. Đâu là cách hiệu quả nhất để giảm các trường hợp extraction sai này?","o":{"A":"Đặt tất cả các trường trong schema là bắt buộc (non-nullable) với các quy tắc kiểm định chặt chẽ để đảm bảo model chỉ xuất ra dữ liệu có thể kiểm chứng.","B":"Thêm chỉ dẫn vào prompt yêu cầu trả về null cho bất kỳ trường nào mà thông tin không được nêu trực tiếp trong nguồn.","C":"Nâng cấp lên một model có năng lực cao hơn với khả năng tuân theo chỉ dẫn tốt hơn để giảm xu hướng hallucination.","D":"Thêm một bước hậu xử lý sử dụng một lệnh gọi LLM thứ hai để xác minh mỗi giá trị được trích xuất có tồn tại trong tài liệu nguồn hay không."}},"96":{"q":"Trợ lý nghiên cứu của bạn giúp người dùng phân tích các bài báo học thuật qua các cuộc hội thoại kéo dài. Kiểm thử người dùng cho thấy một vấn đề lặp lại: sau khi cuộc hội thoại vượt quá 60K token, người dùng đặt các câu hỏi tiếp nối đòi hỏi các chi tiết số liệu chính xác từ các bài báo đã thảo luận trước đó—cỡ mẫu, giá trị p chính xác, các tiêu chí lựa chọn cụ thể. Cách tiếp cận hiện tại của bạn là tóm tắt các cuộc thảo luận về bài báo sau mỗi 8 lượt (turns) để duy trì trong giới hạn context. Người dùng báo cáo rằng các phản hồi cho những câu hỏi đòi hỏi độ chính xác này thường bị rào đón (hedged) hoặc không chính xác. Thay đổi kiến trúc nào là hiệu quả nhất?","o":{"A":"Triển khai cơ chế retrieval để chèn lại (re-inject) các phần liên quan của bài báo khi câu hỏi của người dùng cho thấy họ cần các chi tiết số liệu cụ thể.","B":"Duy trì một cơ sở dữ liệu có cấu trúc chứa các sự kiện chính được trích xuất từ mỗi bài báo (cỡ mẫu, số liệu thống kê, phương pháp) và truy xuất các mục liên quan vào context khi phát hiện các câu hỏi phụ thuộc vào độ chính xác.","C":"Giữ nguyên văn bản nguồn từ các phần phương pháp (methodology) và kết quả (results) trong context vĩnh viễn, trong khi chỉ tóm tắt các phần thảo luận và diễn giải mang tính hội thoại.","D":"Sử dụng một lệnh gọi Claude riêng với chỉ dẫn rõ ràng để tạo ra các bản tóm tắt có độ trung thực cao hơn, giữ lại toàn bộ chi tiết số liệu và giá trị thống kê."}},"97":{"q":"Trợ lý huấn luyện thể hình của bạn sử dụng một system prompt với logic điều kiện chi tiết: \"Nếu người dùng đề cập là người mới bắt đầu, hãy cung cấp hướng dẫn động tác từng bước. Nếu họ dùng các thuật ngữ như 'progressive overload' hoặc 'superset', hãy trả lời ngắn gọn. Nếu họ hỏi về tiền sử chấn thương, luôn khuyến nghị tham khảo ý kiến bác sĩ.\" Trong quá trình evaluation, bạn thấy trợ lý điều chỉnh đúng khi người dùng khai báo rõ ràng trình độ của mình, nhưng gặp khó khăn khi người dùng không nêu rõ trình độ—thường mặc định đưa ra các phản hồi quá chi tiết bất kể các tín hiệu ngữ cảnh như thuật ngữ kỹ thuật. Thay đổi nào đối với system prompt sẽ giải quyết trực tiếp nhất tình trạng không nhận ra các tín hiệu trình độ ngầm này?","o":{"A":"Thêm một chỉ dẫn rõ ràng để model đặt câu hỏi làm rõ về trình độ kinh nghiệm bất cứ khi nào mức độ chuyên môn của người dùng không rõ ràng ngay từ tin nhắn đầu tiên của họ.","B":"Thay thế phần lớn các điều kiện (conditionals) bằng một nguyên tắc chung: \"Điều chỉnh độ sâu giải thích theo trình độ chuyên môn của người dùng, phản chiếu thuật ngữ của họ.\" Chỉ giữ lại điều kiện quan trọng về an toàn liên quan đến tư vấn chấn thương.","C":"Triển khai một bước thu thập thông tin trước hội thoại (pre-conversation intake) yêu cầu người dùng tự đánh giá trình độ kinh nghiệm, sau đó chèn đánh giá đó vào system prompt làm ngữ cảnh cho tất cả các phản hồi tiếp theo.","D":"Thêm nhiều nhánh điều kiện hơn để bao quát thêm các tín hiệu về trình độ chuyên môn, chẳng hạn như \"Nếu người dùng đề cập đến các khoảng số rep cụ thể hoặc hỏi về periodization, coi là nâng cao.\""}},"98":{"q":"Bạn đang xây dựng một quy trình quét bảo mật (security scanning workflow). Khi các kỹ sư cần định vị tất cả các lần xuất hiện của một hàm nguy hiểm như eval() trên một codebase lớn, agent của bạn nên sử dụng tool nào để tìm kiếm nội dung (content search)?","o":{"A":"Sử dụng Grep để tìm kiếm mẫu \"eval(\" trên toàn bộ các file trong codebase.","B":"Sử dụng Glob với một mẫu như **/*eval để tìm các file, sau đó Read từng file khớp mẫu.","C":"Sử dụng Bash để chạy lệnh ls -R | grep eval nhằm liệt kê đệ quy các file chứa eval.","D":"Đọc file chính (entry file) của dự án và lần theo các câu lệnh import để truy vết nơi eval có thể được sử dụng."}},"99":{"q":"Agent đã xác định rằng logic caching trải rộng trên 15 file bao gồm decorator, middleware và các service class (~8.000 dòng tổng cộng). Bước tiếp theo để xây dựng sự hiểu biết trong khi vẫn quản lý các ràng buộc về context là gì?","o":{"A":"Sử dụng Glob để tìm các file khớp với các mẫu caching phổ biến (cache.py, caching/), ưu tiên đọc các file lớn nhất trước, sau đó kiểm tra các file nhỏ hơn để tìm chỗ thiếu sót.","B":"Sử dụng tool Read để tuần tự tải toàn bộ 15 file, xây dựng hiểu biết đầy đủ về toàn bộ phần triển khai caching.","C":"Sử dụng Grep để tìm kiếm các mẫu \"invalidate\" và \"expire\" trên toàn bộ các file, sau đó chỉ Read các khoảng dòng cụ thể đó với ngữ cảnh xung quanh tối thiểu.","D":"Phân tích các import và cây phân cấp lớp (class hierarchies) để xác định lớp cache cơ sở, Read file đó để hiểu interface, sau đó truy vết các phần triển khai invalidation cụ thể."}},"100":{"q":"Hôm nay cô ấy muốn tiếp tục cuộc điều tra cụ thể đó. Cô ấy đã làm việc trên ba codebase khác kể từ đó và biết rằng phiên làm việc (session) đó là \"dive\". Cô ấy nên tiếp tục lại như thế nào?","o":{"A":"Bắt đầu mới hoàn toàn và đọc lại cùng các file đó","B":"Sử dụng --resume auth-deep-dive để tải phiên (session) cụ thể đó theo tên","C":"Sử dụng --continue để tiếp tục từ nơi cuộc hội thoại gần nhất đã dừng lại","D":"Sử dụng --session-id với UUID từ file transcript của phiên hôm qua"}},"101":{"q":"\"Bạn là Lead Data Scientist/Engineer của một dự án quan trọng. Có điều gì đó không hoàn toàn ổn với các chi tiết kỹ thuật hoặc dữ liệu, và nó ảnh hưởng tiêu cực đến các kết quả đầu ra mong đợi. Họ cần độc lập phát triển cả hai cách tiếp cận đối với dữ liệu evaluation... Bạn quản lý tình huống này như thế nào?\"","o":{"A":"Bắt đầu hai phiên (session) mới, để mỗi phiên đọc lại các file nguồn liên quan trước khi bắt đầu.","B":"Tiếp tục trong phiên gốc, phát triển các bài kiểm thử end-to-end trước, sau đó đến các bài kiểm thử snapshot theo tuần tự.","C":"Tiếp tục (resume) phiên phân tích với fork_session được bật, tạo một nhánh riêng cho mỗi chiến lược kiểm thử.","D":"Xuất các phát hiện chính của phiên phân tích ra một file, sau đó tạo hai phiên mới tham chiếu đến file này."}},"102":{"q":"Một cuộc kiểm toán bảo mật yêu cầu nâng cấp thư viện authentication của bạn từ v2 lên v3. Tài liệu hướng dẫn migration ghi rõ các breaking changes: authenticate() giờ trả về một Promise thay vì nhận một callback, kiểu User đã được tái cấu trúc các field, và ba phương thức deprecated đã bị loại bỏ. Grep cho thấy thư viện này được import trong 45 file trải khắp nhiều module. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Dán các breaking changes từ migration guide vào prompt của bạn và sử dụng direct execution để cập nhật tất cả các lượt sử dụng trên 45 file.","B":"Vào plan mode để khảo sát cách thư viện được sử dụng trên các module, lập bản đồ các đường dẫn code bị ảnh hưởng, sau đó tạo một chiến lược migration trước khi triển khai.","C":"Cập nhật phiên bản dependency, chạy test suite, và dùng Claude Code để sửa từng lỗi khi nó xuất hiện.","D":"Tạo một custom slash command đóng gói các phép biến đổi migration, sau đó thực thi nó trên từng file mà không khảo sát codebase trước."}},"103":{"q":"Trong quá trình kiểm thử, bạn quan sát thấy trong các phiên khám phá kéo dài (30+ phút), agent bắt đầu đưa ra các câu trả lời không nhất quán về context đã được thảo luận trước đó. Các kỹ sư báo cáo rằng họ phải nhắc lại context về các module mà họ đã khám phá rồi. Đâu là cách tiếp cận hiệu quả nhất để giải quyết vấn đề này?","o":{"A":"Tạo bản tóm tắt của tất cả các file nguồn trước khi bắt đầu khảo sát, chỉ nạp các bản trình bày đã được nén này vào context.","B":"Chuyển sang một tier model có năng lực cao hơn để có thêm không gian context window cho dữ liệu khảo sát tích lũy.","C":"Triển khai việc tự động xóa context mỗi 15 phút để đảm bảo agent luôn bắt đầu với context mới, không bị nhiễm.","D":"Cho agent duy trì một file scratchpad ghi lại các phát hiện quan trọng, và tham chiếu đến file đó cho các câu hỏi tiếp theo."}},"104":{"q":"Tham số old_string không thể tìm thấy đoạn text duy nhất để khớp — file này có các docstring, tên biến, và các mẫu cấu trúc lặp lại. Đâu là cách đáng tin cậy để hoàn tất việc chèn (insertion) này?","o":{"A":"Dùng Edit với một old_string cực dài, bao trùm hơn 30 dòng ngữ cảnh để đảm bảo tính duy nhất","B":"Dùng Read để nạp file, thêm hàm vào vị trí thích hợp, sau đó dùng Write để ghi lại file đã cập nhật","C":"Dùng tham số replace_all của Edit để nhắm vào một pattern phổ biến và nhúng hàm mới vào trong văn bản thay thế","D":"Dùng Bash để nối thêm định nghĩa hàm vào cuối file bằng cú pháp heredoc"}},"105":{"q":"Bạn cần thêm một kiểm tra validate ngày tháng để đảm bảo ngày diễn ra sự kiện nằm trong tương lai. Việc này chỉ đòi hỏi thêm một câu lệnh điều kiện vào một hàm hiện có trong một file duy nhất. Đâu là cách tiếp cận phù hợp nhất?","o":{"A":"Vào plan mode để phân tích việc validation này có thể ảnh hưởng thế nào đến các phần khác của luồng đặt chỗ (reservation flow)","B":"Bắt đầu với extended thinking mode được bật để đảm bảo suy luận kỹ lưỡng về logic validation","C":"Dùng direct execution để thực hiện thay đổi","D":"Vào plan mode trước để tạo một chiến lược triển khai chi tiết trước khi thực hiện thay đổi"}},"106":{"q":"File CLAUDE.md của nhóm bạn có một quy tắc: \"Sử dụng thụt lề 4 khoảng trắng và luôn chạy Prettier formatting.\" Dù vậy, các buổi code review cho thấy khoảng 30% số file mà Claude Code tạo ra có định dạng không nhất quán — đôi khi thụt lề 2 khoảng trắng, đôi khi thiếu dấu phẩy cuối (trailing comma). Việc thêm nhấn mạnh (\"IMPORTANT: You MUST use Prettier formatting\") giúp giảm số vi phạm xuống còn khoảng 15%, nhưng không loại bỏ hoàn toàn. Đâu là cách hiệu quả nhất để đảm bảo mọi đoạn code được tạo ra đều có định dạng nhất quán?","o":{"A":"Trích xuất các quy tắc định dạng thành một skill riêng mà Claude tự động nạp khi tạo code, kèm theo các ví dụ chi tiết hơn về định dạng đúng.","B":"Thêm một Stop hook với một kiểm tra dựa trên prompt để đánh giá xem code được tạo ra có tuân theo tiêu chuẩn định dạng hay không và nhắc Claude sửa các vi phạm.","C":"Cấu hình một Post ToolUse hook với matcher Edit|Write để tự động chạy Prettier trên mỗi file mà Claude chỉnh sửa.","D":"Tách các quy tắc định dạng thành các file .claude/rules/ có phạm vi theo đường dẫn (path-scoped), được nạp khi Claude làm việc trên các loại file phù hợp."}},"107":{"q":"Bạn đã yêu cầu Claude Code xây dựng một tính năng tạo báo cáo PDF. Bản triển khai ban đầu truy vấn cơ sở dữ liệu chính xác, nhưng phần output có các vấn đề về định dạng: các cột trong bảng quá hẹp khiến nội dung bị cắt ngắn, ngày tháng hiển thị không đúng định dạng, và việc xử lý ngắt trang (page break) không chính xác. Bạn nhận thấy các vấn đề này ảnh hưởng lẫn nhau — thay đổi độ rộng cột ảnh hưởng đến cách ngày tháng hiển thị, và việc ngắt trang phụ thuộc vào chiều cao nội dung. Đâu là cách tiếp cận hiệu quả nhất để lặp dần (iterate) tới một giải pháp hoạt động tốt?","o":{"A":"Giải quyết vấn đề độ rộng cột trước với các số đo cụ thể, xác minh nó hoạt động, sau đó sửa định dạng ngày trong các cột đã được sửa, rồi điều chỉnh ngắt trang — kiểm tra sau mỗi thay đổi.","B":"Cung cấp cả ba vấn đề trong một tin nhắn chi tiết duy nhất với đặc tả chính xác cho từng vấn đề, để Claude xử lý chúng cùng nhau trong một lần cập nhật.","C":"Cho Claude xem một ví dụ về báo cáo được định dạng đúng và yêu cầu nó khớp với kết quả đó, thay vì liệt kê các vấn đề kỹ thuật cụ thể.","D":"Bắt đầu lại từ đầu với một prompt chi tiết nêu rõ tất cả yêu cầu định dạng ngay từ đầu."}},"108":{"q":"Bạn đang triển khai một lớp caching cho các API response nhằm tăng tốc endpoint /products. Bạn có một ý tưởng sơ bộ — dùng Redis với TTL 5 phút — nhưng bạn còn mới trong việc caching cho môi trường production và chưa chắc còn những cân nhắc nào khác mà một triển khai vững chắc (robust) cần có. Đâu là cách hiệu quả nhất để bắt đầu quy trình làm việc lặp (iterative workflow) của bạn?","o":{"A":"Yêu cầu Claude phỏng vấn bạn về các yêu cầu caching trước khi triển khai, làm nổi bật các cân nhắc như chiến lược invalidation, các lớp cache, đảm bảo tính nhất quán, và các trường hợp lỗi (failure modes).","B":"Dùng plan mode để phân tích cách triển khai hiện tại của endpoint /products, sau đó cung cấp yêu cầu caching của bạn sau khi Claude giải thích cấu trúc code hiện có.","C":"Bắt đầu với một yêu cầu tối giản: \"Add Redis caching to /products with 5-minute TTL.\" Bổ sung tính năng và sửa lỗi qua các prompt tiếp theo khi vấn đề xuất hiện trong quá trình kiểm thử.","D":"Viết một bản đặc tả với các yêu cầu đã biết của bạn và các đánh dấu \"TBD\" cho những phần chưa chắc chắn, để Claude đề xuất giải pháp cho từng TBD khi triển khai."}},"109":{"q":"Bạn đang triển khai một thuật toán duyệt đồ thị (graph traversal) phức tạp với các yêu cầu hiệu năng cụ thể và các edge case cần xử lý (các node bị ngắt kết nối, chu trình, cạnh có trọng số). Bạn muốn cấu trúc quy trình làm việc của mình để tinh chỉnh lặp (iterative refinement) hiệu quả cùng Claude. Cách tiếp cận nào sẽ giúp cải thiện tiến bộ (progressive improvement) qua nhiều lần lặp một cách hiệu quả nhất?","o":{"A":"Viết một test suite bao quát hành vi mong đợi, các edge case, và yêu cầu hiệu năng trước khi triển khai. Yêu cầu Claude viết code vượt qua các test, sau đó lặp lại bằng cách chia sẻ các test thất bại với mỗi yêu cầu tinh chỉnh.","B":"Cung cấp cho Claude một đặc tả bằng ngôn ngữ tự nhiên chi tiết về thuật toán, bao gồm tất cả yêu cầu và edge case. Tự tay xem xét từng kết quả và đưa phản hồi mô tả về hành vi cần thay đổi.","C":"Cung cấp cho Claude một reference implementation từ tài liệu, sau đó yêu cầu nó viết lại code cho khớp với phong cách codebase của bạn và thêm phần xử lý edge case cần thiết, đối chiếu kết quả với bản tham chiếu.","D":"Để Claude nghiên cứu kỹ lưỡng thuật toán và tạo một kế hoạch triển khai chi tiết bằng extended thinking, sau đó triển khai toàn bộ giải pháp dựa trên kế hoạch đó."}},"110":{"q":"Nhóm của bạn đang cấu hình các MCP server trong Claude Code. Bạn muốn thêm một server tra cứu địa điểm (venue lookup) dùng chung mà mọi thành viên trong nhóm đều nên có quyền truy cập, và cá nhân bạn muốn thêm một server playlist nhạc thử nghiệm mà chỉ mình bạn đang thử nghiệm. Cách cấu hình nào áp dụng đúng các phạm vi (scope) của MCP server?","o":{"A":"Thêm venue server vào .mcp.json và playlist server vào ~/.claude.json","B":"Thêm cả hai server vào file .mcp.json cấp dự án","C":"Thêm venue server vào ~/.claude.json và playlist server vào .mcp.json","D":"Thêm cả hai server vào ~/.claude.json cục bộ của bạn"}},"111":{"q":"Repository infrastructure-as-code của bạn bao gồm các module Terraform (/terraform/), các manifest Kubernetes (/kubernetes/), và các script pipeline CI/CD (/pipelines/). Mỗi phần yêu cầu các quy ước khác nhau, nhưng file CLAUDE.md gốc duy nhất của bạn đã phình lên hơn 500 dòng. Khi các developer làm việc trên các file Kubernetes, các quy tắc riêng của Terraform lại được nạp vào context một cách không cần thiết, tiêu tốn token. Đâu là cách tiếp cận tốt nhất để tổ chức lại sao cho chỉ hướng dẫn liên quan mới được nạp khi chỉnh sửa từng loại file cụ thể?","o":{"A":"Tái cấu trúc CLAUDE.md gốc thành các phần được gắn nhãn rõ ràng với tiêu đề (ví dụ: \"## Terraform Conventions\"), cải thiện tổ chức và khả năng đọc.","B":"Tách nội dung thành các file CLAUDE.md ở thư mục con (/terraform/CLAUDE.md, /kubernetes/CLAUDE.md), để Claude nạp hướng dẫn theo từng thư mục cụ thể.","C":"Giữ nguyên CLAUDE.md gốc và dùng cú pháp @path/to/import để bao gồm một cách mô-đun các file hướng dẫn theo từng công cụ từ các tài liệu riêng biệt.","D":"Tạo các file trong .claude/rules/ với YAML frontmatter giới hạn theo đường dẫn (ví dụ: paths: [\"terraform/**/*\"]), chỉ nạp các quy tắc khi chỉnh sửa các file phù hợp."}},"112":{"q":"Nhóm của bạn thường xuyên migrate các component React sang Vue. Bạn đã viết một quy trình làm việc từng bước để Claude Code làm theo trong mỗi lần migrate, và bạn muốn mọi developer trong nhóm gọi nó bằng cách gõ /migrate-component. Quy trình này cần được giữ đồng bộ khi nhóm tiếp tục lặp và cải tiến nó. Bạn nên đặt file skill này ở đâu?","o":{"A":"Trong ~/.claude/skills/migrate-component/SKILL.md trên máy của mỗi lập trình viên","B":"Trong .claude/settings.json của dự án, sử dụng một mục skillOverrides để đăng ký và định nghĩa quy trình","C":"Trong .claude/skills/migrate-component/SKILL.md tại thư mục gốc của dự án, được đưa vào version control","D":"Dưới dạng một khối hướng dẫn chi tiết trong file CLAUDE.md gốc của dự án"}},"113":{"q":"Một lỗi (bug) nghiêm trọng đang ảnh hưởng đến người dùng production. Log lỗi cho thấy các exception trong module OrderProcessing với một stack trace rõ ràng chỉ đến một hàm cụ thể. Bạn chưa từng làm việc với module này trước đây. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Bắt đầu bằng direct execution để thu thập thông tin ban đầu, sau đó chuyển sang plan mode để thiết kế một giải pháp toàn diện trước khi triển khai bất kỳ thay đổi nào.","B":"Dùng plan mode để phân tích lỗi trong bối cảnh thiết kế của module, liệt kê các nguyên nhân gốc rễ tiềm ẩn, và ưu tiên các cách sửa một cách có hệ thống.","C":"Vào plan mode để khảo sát kiến trúc và các phụ thuộc của module trước khi thử sửa bất kỳ lỗi nào.","D":"Dùng direct execution để xem xét stack trace, đọc code liên quan, và triển khai một bản sửa lỗi ngay khi bạn xác định được nguyên nhân gốc rễ."}},"114":{"q":"Bạn đang triển khai một module xử lý thanh toán mới, module này phải tuân theo các mẫu (pattern) đã được thiết lập của dự án cho các giao dịch cơ sở dữ liệu, xử lý lỗi, và ghi log kiểm toán (audit logging). Bạn đã xác định được ba module hiện có thể hiện rõ các pattern này: db_utils.py, error_handlers.py, và audit_logger.py. Đây là một tác vụ tích hợp chỉ làm một lần (one-off) — các pattern này đã được ghi chép đầy đủ trong wiki của nhóm và không cần thêm tài liệu ở cấp dự án. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Mô tả các pattern từ ba module bằng ngôn ngữ tự nhiên trong prompt của bạn, giải thích cách xử lý transaction, định dạng lỗi, và các quy ước logging mà Claude nên tuân theo.","B":"Dùng @references để đưa trực tiếp ba module vào prompt của bạn, cung cấp cho Claude các ví dụ code cụ thể về các pattern cần tuân theo.","C":"Yêu cầu Claude khảo sát codebase của bạn để tìm và hiểu các pattern về transaction, xử lý lỗi, và logging trước khi tạo module mới.","D":"Thêm tài liệu về mỗi pattern vào file CLAUDE.md của bạn, thiết lập chúng như các quy ước dự án mà Claude sẽ tự động áp dụng."}},"115":{"q":"Bạn đã yêu cầu Claude viết một script migration dữ liệu, nhưng output ban đầu không xử lý đúng các bản ghi có giá trị null trong các field bắt buộc. Đâu là cách hiệu quả nhất để lặp dần (iterate) tới một giải pháp hoạt động tốt?","o":{"A":"Cung cấp một test case với dữ liệu đầu vào mẫu chứa giá trị null và kết quả đầu ra mong đợi, sau đó yêu cầu Claude sửa nó.","B":"Tự tay chỉnh sửa code đã tạo ra để sửa việc xử lý null, sau đó tiếp tục làm việc với Claude trên các phần khác.","C":"Mô tả chi tiết vấn đề giá trị null và yêu cầu Claude tạo lại toàn bộ script với khả năng xử lý edge case được cải thiện.","D":"Thêm \"think harder about edge cases\" vào prompt của bạn và yêu cầu viết lại hoàn toàn logic migration."}},"116":{"q":"Bạn đã ghi lại các quy ước xử lý lỗi API trong một file CLAUDE.md tại thư mục gốc của dự án, quy định rằng các endpoint handler nên sử dụng một class ApiError tùy chỉnh. Sau vài phiên làm việc, bạn nhận thấy Claude Code đôi khi tuân theo các quy ước này và đôi khi lại dùng các khối try/catch chung chung với thông báo dạng chuỗi (string message). Sự không nhất quán này có vẻ ngẫu nhiên giữa các phiên coding khác nhau. Đâu là bước chẩn đoán đầu tiên hiệu quả nhất?","o":{"A":"Thêm các ví dụ code chi tiết hơn vào CLAUDE.md của bạn, trình bày chính xác pattern sử dụng ApiError cho từng loại endpoint khác nhau.","B":"Chạy /memory để kiểm tra những file memory nào đang được nạp và xác nhận CLAUDE.md của bạn có được bao gồm hay không.","C":"Tìm kiếm các hướng dẫn xung đột trong ~/.claude/CLAUDE.md hoặc ~/.claude/rules/ có thể ghi đè lên các quy ước dự án của bạn.","D":"Tạo các quy tắc theo đường dẫn cụ thể trong claude/rules/handlers.md với YAML frontmatter giới hạn phạm vi các hướng dẫn xử lý lỗi cho các file handler API của bạn."}},"117":{"q":"Monorepo của bạn chứa các tiêu chuẩn coding dùng chung tại /docs/standards/security-rules.md (dành cho các service xử lý dữ liệu người dùng), testing-patterns.md (dành cho tất cả các package), và api-conventions.md (dành cho các service hướng API). 15 package của bạn được tổ chức theo miền tính năng (feature domain) (/packages/auth/, /packages/billing/, /packages/notifications/, v.v.) mà không có quy ước đặt tên nào cho biết package nào xử lý dữ liệu người dùng hay expose API. Các package maintainer được kỳ vọng tự cấu hình các thiết lập phát triển cục bộ của riêng họ, vì họ hiểu rõ các yêu cầu miền (domain) của package mình. Hiện tại, tất cả các file CLAUDE.md của package đều lặp lại cả ba tiêu chuẩn, áp dụng cả những hướng dẫn không liên quan. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Tạo các file claude/rules/ cho từng tiêu chuẩn, với YAML frontmatter liệt kê đường dẫn tới mọi thư mục package mà tiêu chuẩn đó cần áp dụng.","B":"Tạo một shared-standards.md sử dụng @imports để gộp cả ba tiêu chuẩn lại, sau đó để CLAUDE.md của mỗi package import file gộp đó.","C":"Đặt tất cả các tiêu chuẩn vào CLAUDE.md gốc kèm theo các hướng dẫn ghi đè kiểu \"ignore security-rules.md when working in packages that don't handle user data.\"","D":"Dùng @imports trong CLAUDE.md của mỗi package để chỉ tham chiếu đến các file tiêu chuẩn cụ thể liên quan đến package đó, dựa trên kiến thức chuyên môn của người phụ trách (maintainer)."}},"118":{"q":"Hệ thống xử lý các đánh giá sản phẩm (product review) bằng tool use với một schema được định nghĩa sẵn: rating (số nguyên 1-5), pros (mảng chuỗi), cons (mảng chuỗi), và overall_sentiment (enum: positive, negative, mixed). Kiểm thử cho thấy hai vấn đề với các đánh giá ngắn gọn hoặc mơ hồ (~20% tập dữ liệu): (1) với các đánh giá như \"Great product!\", Claude bịa ra các pros và cons cụ thể thay vì chỉ ra rằng thông tin này không được nêu rõ, và (2) với các đánh giá mang tính mỉa mai như \"Well that was... interesting\", Claude chọn sentiment một cách tùy tiện vì không có lựa chọn nào cho các trường hợp mơ hồ. Thay đổi schema nào giải quyết tốt nhất cả hai vấn đề này?","o":{"A":"Thêm một trường extraction_confidence (0.0-1.0) cho mỗi giá trị, và lọc bỏ các kết quả đầu ra mà bất kỳ độ tin cậy nào rơi xuống dưới một ngưỡng.","B":"Cho phép giá trị null đối với pros/cons, và thêm \"unclear\" vào enum sentiment.","C":"Cho phép mảng rỗng đối với pros/cons như một kết quả đầu ra hợp lệ, và thêm \"unclear\" vào enum sentiment.","D":"Biến pros và cons thành các trường tùy chọn (optional), và thêm \"neutral\" và \"unclear\" vào enum sentiment."}},"119":{"q":"Sau khi lô xử lý (batch) hàng ngày gồm 10.000 tài liệu hoàn tất, 300 tài liệu (3%) thất bại với lỗi \"context_length_exceeded\". File kết quả xác định từng lỗi bằng custom_id. Đâu là cách tiếp cận tiết kiệm chi phí nhất để xử lý các lỗi này?","o":{"A":"Xử lý lại toàn bộ batch với prompt caching được bật để giảm chi phí khi thử lại các request có system prompt giống hệt nhau","B":"Chỉ gửi lại 300 tài liệu bị lỗi sau khi chia nhỏ chúng thành các phần nhỏ hơn, sau đó ghép các kết quả trích xuất một phần lại với nhau","C":"Tăng tham số max_tokens cho 300 tài liệu bị lỗi và gửi lại chúng trong một batch mới","D":"Gửi lại toàn bộ batch 10.000 tài liệu bằng một tier model có context window lớn hơn"}},"120":{"q":"Hệ thống cần trích xuất thông tin ứng viên (tên, thông tin liên hệ, kỹ năng, kinh nghiệm làm việc, học vấn) từ các bản resume được tải lên. Dữ liệu trích xuất phải tuân thủ nghiêm ngặt một JSON schema được định nghĩa trước, vì việc thiếu các field bắt buộc hoặc sai kiểu dữ liệu sẽ gây ra lỗi validate ở các bước xử lý tiếp theo (downstream). Đâu là cách tiếp cận đáng tin cậy nhất để đảm bảo output của Claude luôn khớp với schema?","o":{"A":"Định nghĩa một tool với input schema khớp với cấu trúc JSON bạn yêu cầu, và trích xuất dữ liệu từ phản hồi tool_use của Claude.","B":"Đưa các hướng dẫn định dạng JSON chi tiết cùng một ví dụ mẫu (template) vào system prompt, yêu cầu Claude chỉ xuất ra JSON hợp lệ.","C":"Parse phản hồi dạng text của Claude bằng các mẫu regex để trích xuất các đối tượng JSON, sử dụng cơ chế retry cho các phản hồi bị lỗi định dạng.","D":"Thực hiện hai lượt gọi API riêng biệt — trước tiên trích xuất thông tin dưới dạng text, sau đó yêu cầu Claude định dạng đoạn text đó thành JSON."}},"121":{"q":"Sau khi triển khai tính năng review code tự động, các developer báo cáo rằng khoảng 35% các phát hiện (finding) được gắn cờ là false positive, rơi vào các mẫu nhất quán: gợi ý về style mâu thuẫn với quy ước của nhóm, cảnh báo bảo mật cho các pattern vốn an toàn trong bối cảnh triển khai (deployment context) của bạn, và các gợi ý về hiệu năng mà nếu áp dụng sẽ làm giảm hiệu năng cho use case cụ thể của bạn. Bạn muốn giảm false positive trong khi vẫn giữ khả năng phát hiện các vấn đề thực sự. Cách tiếp cận nào giúp model tổng quát hóa (generalize) khả năng phán đoán của nó tốt nhất đối với các mẫu code mới mà nó chưa từng gặp?","o":{"A":"Đưa các ví dụ few-shot vào prompt của bạn, minh họa các đoạn code có chú thích phân biệt các pattern chấp nhận được với các vấn đề thực sự trong từng danh mục.","B":"Triển khai một bước post-processing sử dụng khớp từ khóa (keyword matching) để lọc bỏ các phát hiện chứa các từ như \"convention,\" \"context-dependent,\" hoặc \"trade-off.\"","C":"Thêm hướng dẫn vào system prompt của bạn để \"be conservative,\" \"only flag definite issues,\" và \"consider that some patterns may be intentional.\"","D":"Tạo một bản đặc tả viết chi tiết về tất cả các pattern không nên bị gắn cờ (flagged), sau đó đưa toàn bộ tài liệu này vào system prompt."}},"122":{"q":"Sau khi mở rộng bộ MCP tools của agent với các khả năng chuyên biệt cho giao hàng (check_delivery_status, contact_driver, issue_credit, apply_promo_code, update_delivery_address, reschedule_delivery), tổng số tool đã tăng từ 4 lên 10. Bộ evaluation của bạn cho thấy tool selection accuracy đã giảm xuống còn 71%. Phân tích log cho thấy phần lớn lỗi liên quan đến việc agent chọn nhầm giữa các tool có ý nghĩa trùng lặp về mặt ngữ nghĩa - gọi issue_credit trong khi process_refund mới là lựa chọn đúng, và gọi check_delivery_status trong khi lookup_order đã trả về dữ liệu cần thiết. Cách tiếp cận nào giúp loại bỏ tận gốc (về mặt cấu trúc) sự trùng lặp ngữ nghĩa đang được ghi nhận là nguyên nhân gây lỗi?","o":{"A":"Chia các tool ra hai subagent - một agent \"financial resolution\" (giải quyết tài chính) gồm process_refund, issue_credit, và apply_promo_code, và một agent \"delivery\" (giao hàng) gồm các tool giao hàng còn lại - với một coordinator điều phối giữa chúng.","B":"Thêm các few-shot examples vào system prompt minh họa cách lựa chọn đúng cho từng cặp tool mơ hồ, chẳng hạn cho thấy khi nào issue_credit hay process_refund là phù hợp.","C":"Hợp nhất các tool trùng lặp về mặt ngữ nghĩa - gộp issue_credit và process_refund thành một tool resolve_compensation duy nhất với một flag include_tracking tùy chọn.","D":"Bật tool search tool với defer_loading trên sáu tool mới, giữ bốn tool ban đầu luôn được load sẵn, để agent gọi tool search một cách linh hoạt khi cần."}},"123":{"q":"Tài liệu về tool use của Anthropic nêu rõ: \"Write instructive error messages. Instead of generic errors like 'failed', include what went wrong and what Claude should try next.\" Một agent xử lý tranh chấp hóa đơn (billing dispute) sử dụng lookup_order, tool này bắt (catch) tất cả exception và trả về một tool_result với is_error: true kèm thông báo \"execution failed\". Việc giám sát (monitoring) cho thấy hai kiểu lỗi: agent lặp lại y hệt lệnh gọi đó cho đến khi chạm giới hạn turn, hoặc nó lập tức gọi escalate_to_human mà không thử các tool thay thế. Thay đổi nào tuân theo khuyến nghị nêu trên và cung cấp cho Claude thông tin cần thiết để chọn đúng hành động khôi phục (recovery action) cho từng loại lỗi?","o":{"A":"Triển khai retry logic với exponential backoff bên trong từng tool implementation để các lỗi tạm thời (transient errors) được xử lý một cách minh bạch ngay trong tool trước khi bất kỳ kết quả lỗi nào được hiển thị cho Claude trong agentic loop.","B":"Trả về các thông báo riêng theo từng loại lỗi với is_error: true, ví dụ: \"order not found - try get_customer to search by phone\" cho lỗi dữ liệu và \"Database timeout (transient) - retry should succeed\" cho lỗi hạ tầng.","C":"Bỏ is_error: true và trả về chi tiết lỗi như nội dung tool bình thường, để Claude suy luận về phản hồi đó như dữ liệu thay vì coi đó là một điều kiện lỗi được gắn cờ làm thiên lệch hành vi retry.","D":"Thêm một bước phân loại lỗi trong agentic loop để chặn các lỗi tool trước khi Claude nhìn thấy, gắn nhãn mỗi lỗi là \"retry\", \"try_alternative,\" hoặc \"escalate,\" và thêm khuyến nghị đó vào tool result."}},"124":{"q":"Prompt code review của bạn bao gồm cả các thay đổi implementation lẫn file test tương ứng, nhưng các nhận xét review của LLM lại không chỉ ra được các đường thực thi (code path) chưa được test. Phân tích cho thấy model xác định đúng các hàm hoàn toàn không có test nào, nhưng lại không phát hiện được khi các nhánh điều kiện (conditional branch) hoặc đường xử lý lỗi (error-handling path) bên trong các hàm đã có test vẫn thiếu coverage. Đâu là cách hiệu quả nhất để cải thiện khả năng phát hiện các lỗ hổng coverage ở cấp độ nhánh (branch-level) mà không làm pipeline trở nên quá phức tạp?","o":{"A":"Triển khai một pipeline nhiều bước (multi-pass), trong đó các lệnh gọi LLM riêng biệt trước tiên trích xuất tất cả các nhánh điều kiện (conditional branches), sau đó đối chiếu từng nhánh với các test assertion trong bước thứ hai.","B":"Bao gồm các few-shot examples cho thấy đoạn code có một nhánh chưa được kiểm thử (uncovered branch) đi kèm với bình luận review xác định cụ thể test case còn thiếu.","C":"Thêm các hướng dẫn rõ ràng chỉ đạo model liệt kê từng nhánh điều kiện và đường dẫn ngoại lệ (exception path), sau đó xác minh mỗi nhánh có một test assertion tương ứng.","D":"Tái cấu trúc prompt để xen kẽ implementation và test, trình bày mỗi function ngay sau đó là các test case của nó."}},"125":{"q":"Sau khi triển khai automated review, bạn nhận thấy precision cao nhưng recall thấp - các bug thật đang lọt qua mà không bị phát hiện. Điều tra cho thấy prompt review của bạn yêu cầu Claude \"only report high-confidence issues you are certain about\" và \"err on the side of not commenting\". Các developer đánh giá cao việc ít nhiễu (low noise), nhưng một race condition từng gây ra sự cố production đã hiện diện trong một PR đã được review mà không hề bị báo cáo. Bạn cần cải thiện đáng kể khả năng phát hiện bug trong khi vẫn giữ tỷ lệ false positive ở mức chấp nhận được cho team. Đâu là cách tiếp cận hiệu quả nhất?","o":{"A":"Mở rộng context window bằng cách bao gồm các file test liên quan, lịch sử git gần đây, và dependency graph của module cùng với diff, giúp Claude có nhiều tín hiệu phong phú hơn để đánh giá mức độ nghiêm trọng của vấn đề.","B":"Loại bỏ các hướng dẫn lọc thận trọng (conservative filtering) và yêu cầu Claude báo cáo tất cả các vấn đề tiềm ẩn, sau đó áp dụng một bộ lọc lập trình để loại bỏ trùng lặp và ẩn các danh mục mà trước đây thường tạo ra false positive.","C":"Chia việc review thành một giai đoạn phát hiện (finding stage), trong đó mục tiêu của Claude là bao phủ toàn diện (coverage) - gắn cờ mọi vấn đề tiềm ẩn kèm metadata về độ tin cậy (confidence) và mức độ nghiêm trọng (severity) - và một giai đoạn riêng biệt áp dụng ngưỡng (threshold) cho các phát hiện đó.","D":"Thêm các few-shot examples chi tiết minh họa các danh mục lỗi mà Claude nên gắn cờ - race condition, null dereference, thiếu xử lý lỗi - trong khi vẫn giữ hướng dẫn lọc theo độ tin cậy (confidence filtering) để duy trì mức độ chính xác (precision) hiện tại."}},"126":{"q":"Automated reviewer của bạn dùng một prompt duy nhất bao quát các vấn đề security, API design, và business logic correctness. Bộ evaluation của bạn cho thấy recall mạnh cho các phát hiện về API design (82%) nhưng recall kém cho các edge case về business logic trong quiz scoring (34%). Khi bạn thêm các few-shot example về logic bug vào prompt, logic recall tăng lên 41% nhưng API design recall lại giảm xuống 68%. Bạn nên xử lý sự đánh đổi (trade-off) này như thế nào để cải thiện khả năng phát hiện ở cả hai hạng mục?","o":{"A":"Chia việc review thành các prompt tập trung riêng biệt - một cho bảo mật và thiết kế API, một cho logic nghiệp vụ - mỗi prompt có các ví dụ riêng, sau đó gộp các phát hiện lại trước khi đăng.","B":"Nâng cấp lên một model tier mạnh hơn, vì khả năng suy luận mạnh hơn của nó sẽ xử lý được cả hai loại vấn đề trong một prompt duy nhất và loại bỏ đánh đổi về recall.","C":"Cung cấp toàn bộ repository làm context thay vì chỉ các file đã thay đổi và đoạn code xung quanh, giúp model có cái nhìn sâu hơn về logic nghiệp vụ.","D":"Thay thế các few-shot examples bằng một checklist chi tiết các trường hợp biên (edge case) cụ thể của logic cần kiểm tra, chẳng hạn như chia cho 0 (division-by-zero) trong tính điểm hoặc các ngưỡng xếp loại (grading thresholds)."}},"127":{"q":"Agent của bạn đang xử lý một tranh chấp hóa đơn (billing dispute). Sau khi gọi get_customer và lookup_order, nó xác định rằng tranh chấp này liên quan đến một lỗi giá khuyến mãi (promotional pricing error) cần được phê duyệt (approval) - vượt quá quyền hạn (authorization level) của agent. Quy trình làm việc nên xử lý việc leo thang (escalation) giữa chừng này như thế nào?","o":{"A":"Lưu trữ (persist) toàn bộ lịch sử cuộc hội thoại và phản hồi tool vào một database, sau đó gọi escalate_to_human kèm một reference ID.","B":"Biên soạn một bản bàn giao (handoff) có cấu trúc gồm thông tin khách hàng, thông tin đơn hàng, và vấn đề đã xác định trước khi gọi escalate_to_human.","C":"Vẫn thử thực hiện hoàn tiền bằng process_refund, chỉ escalate nếu hệ thống từ chối giao dịch.","D":"Gọi escalate_to_human chỉ với tin nhắn gốc của khách hàng."}},"128":{"q":"Agent của bạn đã gọi lookup_order nhiều lần trong khi điều tra yêu cầu trả hàng (return request) của khách hàng. Mỗi phản hồi bao gồm hơn 40 field (items, shipping details, payment info, status history). Tool output hiện chiếm phần lớn context của cuộc hội thoại. Khách hàng đề cập thêm hai đơn hàng khác mà họ muốn thảo luận. Đâu là cách tiếp cận hiệu quả trước khi thực hiện thêm các lookup?","o":{"A":"Chỉ trích xuất các trường liên quan đến việc trả hàng (items, ngày mua, thời hạn trả hàng, trạng thái) từ mỗi phản hồi order hiện có, loại bỏ các chi tiết rườm rà.","B":"Tiếp tục thực hiện thêm các lookup mà không sửa đổi context đầu ra tool hiện có.","C":"Chuyển tất cả các phản hồi tool sang một vector database có đánh chỉ mục ngữ nghĩa (semantic indexing), truy xuất các phần liên quan khi cuộc hội thoại tiếp diễn.","D":"Để model tạo một bản tóm tắt bằng ngôn ngữ tự nhiên cho các chi tiết chính của mỗi đơn hàng, thay thế các phản hồi có cấu trúc bằng mô tả dạng văn xuôi."}},"129":{"q":"Log production cho thấy khi agent xử lý các tranh chấp hóa đơn phức tạp cần từ 6 tool call trở lên, đôi khi nó chạm giới hạn max_turns sau khi đã thu thập dữ liệu nhưng trước khi hoàn tất việc giải quyết hoặc leo thang (escalate). Mục tiêu của team là đảm bảo mọi tương tác với khách hàng đều kết thúc bằng một trong hai kết quả: giải quyết hoàn tất hoặc leo thang lên con người (human escalation), bất kể agent loop kết thúc theo cách nào. Cách tiếp cận nào đạt được sự đảm bảo này?","o":{"A":"Thêm code ở lớp orchestration để kiểm tra kết quả của agent sau mỗi lần kết thúc loop - nếu loop kết thúc mà không có một resolution hoàn chỉnh hoặc escalation, gọi escalate_to_human bằng lập trình kèm theo context hội thoại tích lũy và kết quả tool.","B":"Triển khai một pre-tool-use hook đếm số lần gọi tool và kết thúc loop với một escalation tự động khi agent đạt 80% số hành động còn lại của nó.","C":"Thêm hướng dẫn vào system prompt yêu cầu agent gọi escalate_to_human kèm bản tóm tắt các phát hiện của nó bất cứ khi nào nó xác định rằng không thể giải quyết tranh chấp.","D":"Chia quy trình thành hai lần gọi agent tuần tự - agent đầu tiên thu thập thông tin qua get_customer và lookup_order, sau đó agent thứ hai sử dụng dữ liệu đó và xử lý process_refund hoặc escalate_to_human, mỗi agent có ngân sách lượt (turn budget) riêng."}},"130":{"q":"Agent phân tích tài liệu (document analysis agent) có một tool duy nhất là analyze_document, nhận vào một document và một tham số instruction dạng free-text. Trong quá trình evaluation, các yêu cầu như \"key financial metrics\" thường trả về các bản tóm tắt tường thuật (narrative summary), trong khi \"summarize the methodology\" đôi khi lại trả về các bảng dữ liệu thô (raw data table). Synthesis agent báo cáo rằng kết quả phân tích cần phải được yêu cầu lại (re-request) với instruction đã được làm rõ hơn. Đâu là cách hiệu quả nhất để cải thiện độ tin cậy (reliability)?","o":{"A":"Cải thiện phần mô tả (description) của tool bằng các ví dụ chi tiết cho thấy các cách diễn đạt hướng dẫn khác nhau nên ánh xạ tới các định dạng đầu ra khác nhau như thế nào.","B":"Giữ nguyên một tool duy nhất nhưng thêm một tham số enum loại phân tích (analysis type) yêu cầu lựa chọn rõ ràng giữa extraction, summarization, và verification.","C":"Để coordinator phân loại trước (pre-classify) từng yêu cầu phân tích trước khi chuyển hướng dẫn cho document analysis agent.","D":"Chia tool tổng quát thành các tool chuyên biệt theo mục đích - trích xuất data point, tóm tắt nội dung, xác minh claim so với nguồn - mỗi tool có"}},"131":{"q":"Trong production, bạn quan sát thấy các truy vấn kiểm tra sự kiện (fact-checking) đơn giản (ví dụ: \"What year was the Paris Climate Agreement signed?\") đều đi qua tuần tự cả bốn subagent, tiêu tốn hơn 40 giây và một lượng token đáng kể cho mỗi truy vấn. Trong khi đó, các nghiên cứu so sánh phức tạp lại được hưởng lợi từ toàn bộ pipeline. Phân bố truy vấn của bạn rất đa dạng và đang thay đổi liên tục khi người dùng khám phá ra các ứng dụng mới. Đâu là cách tiếp cận hiệu quả nhất để tối ưu cho các mức độ phức tạp truy vấn khác nhau?","o":{"A":"Để coordinator phân tích từng query và linh hoạt quyết định nên gọi subagent nào dựa trên đánh giá của nó về yêu cầu của query.","B":"Huấn luyện một bộ phân loại độ phức tạp của query (query complexity classifier) trên dữ liệu lịch sử đã gán nhãn để dự đoán tổ hợp subagent tối ưu, huấn luyện lại định kỳ khi các mẫu query thay đổi.","C":"Tạo một fast-path cho các câu hỏi mang tính sự kiện (factual questions) bỏ qua hoàn toàn subagent, định tuyến tất cả các query còn lại qua toàn bộ pipeline để đảm bảo việc nghiên cứu được thấu đáo.","D":"Triển khai định tuyến dựa trên mẫu (pattern-based routing) phân loại query theo cấu trúc (single-fact so với comparative so với analytical) và ánh xạ mỗi loại tới một tổ hợp được định sẵn."}},"132":{"q":"Multi-agent research pipeline của bạn bị crash sau khi xử lý được 12 trong số 28 document. Web search agent đã xác định được các nguồn liên quan, document analyzer đã hoàn thành một phần việc trích xuất (extraction), còn synthesizer đã bắt đầu xác định các pattern. Bạn cần tiếp tục xử lý mà không lặp lại công việc đã làm hoặc làm mất đi độ chính xác (fidelity) của các phát hiện trước đó. Cách tiếp cận quản lý state nào cân bằng tốt nhất giữa độ chính xác thông tin (information fidelity) và hiệu quả sử dụng context khi khôi phục trạng thái agent?","o":{"A":"Đánh chỉ mục (index) tất cả đầu ra của agent vào một vector store dùng chung. Khi resume, mỗi agent truy vấn vector store bằng semantic search để lấy lại các phát hiện trước đó có liên quan.","B":"Để mỗi agent tự duy trì một file trạng thái (state file) bền vững riêng và tự tải lại một cách độc lập vào đầu mỗi session.","C":"Để mỗi agent lưu (persist) một bản export có cấu trúc tại một vị trí đã biết. Khi resume, coordinator tải manifest và đưa trạng thái liên quan vào các prompt của agent.","D":"Lưu lại (persist) conversation log của coordinator chứa tất cả các lần ủy quyền tác vụ (task delegation) và phản hồi, cung cấp log này cho các agent khi resume."}},"133":{"q":"Agent của bạn đã phân tích một service module phức tạp - đọc 23 file mã nguồn, truy vết các luồng request, và xác định các pattern xử lý lỗi. Một developer cần phát triển hai chiến lược testing trước khi quyết định chọn một: end-to-end test với các external service được mock (mocked) so với snapshot test ghi lại các output kỳ vọng. Developer này cần phát triển độc lập cả hai cách tiếp cận để đánh giá sự đánh đổi (trade-off) giữa chúng. Bạn nên quản lý các session như thế nào?","o":{"A":"Resume session phân tích với fork_session được bật, tạo một nhánh (branch) riêng cho mỗi chiến lược testing.","B":"Export các phát hiện chính của session phân tích ra một file, sau đó tạo hai session mới tham chiếu tới file này.","C":"Tiếp tục trong session gốc, phát triển end-to-end test trước, sau đó lần lượt đến snapshot test.","D":"Bắt đầu hai session mới, mỗi session tự đọc lại các file mã nguồn liên quan trước khi bắt đầu."}},"134":{"q":"Giám sát production cho thấy giai đoạn nghiên cứu (research phase) mất nhiều thời gian hơn dự kiến. Phân tích cho thấy coordinator gọi subagent web search, sau đó gọi subagent document analysis và lại chờ tiếp. Hai tác vụ này độc lập với nhau - không tác vụ nào cần output của tác vụ kia. Đâu là cách hiệu quả nhất để chạy các subagent này đồng thời (concurrently)?","o":{"A":"Chuyển cả hai subagent sang dùng model tier Haiku thay vì Sonnet để giảm thời gian thực thi riêng của từng subagent.","B":"Tạo một lớp orchestration bất đồng bộ (async) bên ngoài agent để sinh ra các thread song song, mỗi thread chạy một coordinator riêng.","C":"Cấu trúc coordinator để phát ra cả hai lệnh gọi Task tool (cho web search và document analysis) trong cùng một tin nhắn phản hồi.","D":"Thêm hướng dẫn chi tiết vào system prompt của coordinator giải thích lợi ích về hiệu năng của việc thực thi song song cùng lúc."}},"135":{"q":"Hôm qua, một kỹ sư đã sử dụng agent để phân tích một module xác thực (authentication) kiểu legacy, xác định được hai cách tiếp cận refactor khác nhau: tách ra thành microservice riêng so với refactor tại chỗ (in-place). Hôm nay, họ muốn khám phá sâu cả hai cách tiếp cận - để agent đề xuất các thay đổi code cụ thể cho từng cách - trước khi quyết định sẽ triển khai cách nào. Đâu là cách hiệu quả nhất để cấu trúc việc khám phá này?","o":{"A":"Dùng fork_session để tạo hai nhánh từ phân tích của ngày hôm qua, khám phá một cách tiếp cận trong mỗi fork.","B":"Resume session của ngày hôm qua và khám phá cả hai cách tiếp cận lần lượt trong cùng một luồng hội thoại.","C":"Resume session của ngày hôm qua để khám phá cách tiếp cận đầu tiên, sau đó bắt đầu một session mới cho cách thứ hai, tự tái tạo lại context ban đầu theo cách thủ công.","D":"Bắt đầu hai session mới, tự cung cấp một bản tóm tắt các phát hiện phân tích của ngày hôm qua để thiết lập context theo cách thủ công."}},"136":{"q":"Một kỹ sư yêu cầu agent của bạn bổ sung test toàn diện cho một codebase legacy gồm 200 file với test coverage hiện có rất ít. Vì kỹ sư này chưa dành nhiều thời gian tìm hiểu codebase, họ nhờ agent giúp xác định nên ưu tiên module nào trước. Agent nên phân rã (decompose) tác vụ mở (open-ended) này như thế nào?","o":{"A":"Dùng Glob và Grep để lập bản đồ cấu trúc codebase, xác định các module gắn kết chặt chẽ (heavily-coupled), tạo một kế hoạch ưu tiên cho các khu vực có tác động cao, và điều chỉnh khi phát hiện thêm các phụ thuộc (dependency).","B":"Tạo trước một lịch trình testing cố định dựa trên cấu trúc thư mục, phân bổ công sức đều nhau cho mỗi thư mục cấp cao nhất bất kể độ phức tạp hay tầm quan trọng của code.","C":"Đọc một cách có hệ thống toàn bộ 200 file để tạo một bản kiểm kê (inventory) đầy đủ các function trước khi viết bất kỳ test nào, đảm bảo kế hoạch testing bao quát mọi thứ ngay từ đầu.","D":"Bắt đầu viết test cho module đầu tiên theo thứ tự bảng chữ cái, dùng các lỗi test thất bại và import để khám phá các file liên quan một cách tự nhiên."}},"137":{"q":"Automated review của bạn gọi Claude API cho mỗi PR, sử dụng tool_use với một tool report_findings trả về một mảng JSON các finding object (mỗi object gồm file_path, line_number, severity, category, và description). Khi test trên một PR lớn chạm vào hơn 30 file, response đạt tới giới hạn max_tokens và output bị cắt cụt (truncated) giữa chừng JSON, khiến parser của pipeline gặp lỗi. Đâu là cách hiệu quả nhất để xử lý tình huống này?","o":{"A":"Tăng max_tokens lên mức tối đa của model và yêu cầu Claude giữ mỗi mô tả phát hiện dưới 50 từ.","B":"Chuyển từ tool_use sang việc prompt Claude trả về các phát hiện dưới dạng danh sách markdown.","C":"Chia việc review thành nhiều lệnh gọi API, mỗi lệnh phân tích một tập con của các file đã thay đổi, sau đó gộp các mảng findings kết quả lại.","D":"Thêm retry logic để phát hiện JSON bị cắt cụt (truncated) và gửi lại yêu cầu kèm hướng dẫn chỉ báo cáo các phát hiện có mức độ nghiêm trọng critical và high."}},"138":{"q":"Bạn đang thiết lập một pipeline automated code review non-interactive bằng Claude Code. Bạn muốn Claude phân tích một Git diff đã lấy (git diff) so với nhánh main và áp dụng một bộ hướng dẫn code review tùy chỉnh (custom). Tuy nhiên, bạn nhận thấy khi chạy pipeline, Claude chỉ nhìn vào phần văn bản diff thô và hoàn toàn ngừng sử dụng các tool đọc file hay điều hướng code của nó. Kết quả là nó không kiểm tra được bối cảnh (context) rộng hơn của repository, điều này rất quan trọng vì diff này sửa đổi một hàm cốt lõi (core function) được nhiều module bên ngoài khác gọi đến. Thay đổi nào trong lệnh gọi CLI sẽ khiến Claude đọc các file liên quan trong repository trong khi vẫn áp dụng thành công các hướng dẫn review tùy chỉnh của bạn?","o":{"A":"Thay --system-prompt bằng --append-system-prompt để các hướng dẫn review của bạn được thêm vào prompt mặc định của Claude Code thay vì ghi đè lên hướng dẫn có sẵn cho việc dùng các tool đọc file và điều hướng code.","B":"Giữ --system-prompt và thêm --allowedTools \"Read, Glob, Grep\" để chế độ non-interactive cho phép các tool hệ thống file mà nó vốn tắt.","C":"Ngừng pipe diff qua stdin và thay vào đó nhúng nội dung diff vào trong chuỗi prompt, để Claude Code xử lý lệnh gọi này như một agentic session thay vì một phiên xử lý luồng (stream-processing).","D":"Bỏ hẳn --system-prompt và đặt các hướng dẫn review vào một file CLAUDE.md tại thư mục gốc repo, vì --system-prompt không tương thích với việc dùng tool khi chạy dưới -p."}},"139":{"q":"Team phát triển của bạn đang dùng Claude Code để tự động hóa việc tạo test trên một codebase lớn. Tuy nhiên, các developer thường xuyên từ chối các bộ test được tạo ra vì Claude tạo ra một lượng lớn assertion tầm thường hoặc các test chỉ nhằm tối đa hóa line coverage mà không kiểm chứng logic hành vi có ý nghĩa hay các edge case. Bạn muốn hướng dẫn Claude tạo ra ngay từ đầu các test chất lượng cao, sẵn sàng cho production, mà không gây độ trễ (latency) cao hay phải sửa đổi pipeline script cốt lõi. Chiến lược nào đảm bảo tốt nhất rằng các test chất lượng cao, có ý nghĩa sẽ được tạo ra ngay từ đầu?","o":{"A":"Giới hạn việc tạo test ở các thư mục mà chỉ số chất lượng lịch sử cho thấy tỷ lệ chấp nhận cao hơn, tắt tính năng này ở các khu vực mà test được tạo ra thường xuyên cần chỉnh sửa nhiều.","B":"Thêm phân tích độ bao phủ (coverage) sau khi tạo test, tự động lọc bỏ bất kỳ test được tạo nào không làm tăng độ bao phủ dòng (line coverage) so với mức mà các test hiện có đã cung cấp.","C":"Ghi lại các tiêu chuẩn testing trong CLAUDE.md, bao gồm các tiêu chí test có giá trị, các fixture khả dụng kèm mục đích sử dụng dự kiến, và các ví dụ phân biệt giữa test hành vi có ý nghĩa (meaningful behavioral test) với các assertion tầm thường.","D":"Triển khai việc tạo test theo hai giai đoạn, trong đó một lệnh gọi Claude thứ hai chấm điểm từng test theo tiêu chí chất lượng, lọc bỏ các test điểm thấp trước khi trình bày kết quả cho developer."}},"140":{"q":"Một developer dùng Claude Code để refactor một hàm trong phiên làm việc (session) của họ. Trước khi commit, họ yêu cầu chính session Claude đó review lại code để tìm vấn đề. Sau đó, một automated CI review riêng biệt lại phát hiện ra một số bug mà review trong cùng session đã bỏ sót. Điều gì giải thích tốt nhất cho sự khác biệt này?","o":{"A":"Môi trường CI có quyền truy cập vào toàn bộ context của codebase trong khi session cục bộ (local) chỉ thấy file hiện tại.","B":"Bản review trên CI dùng một prompt cụ thể hơn, được thiết kế riêng để bắt lỗi, trong khi yêu cầu của developer thì quá chung chung.","C":"Claude giữ lại context về suy luận trước đó của nó trong session, khiến nó ít có khả năng đặt câu hỏi lại với các quyết định của chính mình.","D":"Thời lượng session kéo dài khiến context window bị lấp đầy bởi lịch sử hội thoại, để lại ít không gian hơn cho việc phân tích thấu đáo."}},"141":{"q":"Automated reviewer của bạn dùng một prompt duy nhất bao quát các vấn đề security, API design, và business logic correctness. Bộ evaluation của bạn cho thấy recall mạnh cho các phát hiện về API design (82%) nhưng recall kém cho các edge case về business logic trong quiz scoring (34%). Khi bạn thêm các few-shot example về logic bug vào prompt, logic recall cải thiện lên 41% nhưng API design recall lại giảm xuống 68%. Bạn nên xử lý sự đánh đổi (trade-off) này như thế nào để cải thiện khả năng phát hiện ở cả hai hạng mục?","o":{"A":"Chia việc review thành các prompt tập trung riêng biệt - một cho bảo mật và thiết kế API, một cho logic nghiệp vụ - mỗi prompt có các ví dụ riêng, sau đó gộp các phát hiện lại trước khi đăng.","B":"Thay thế các few-shot examples bằng một checklist chi tiết các trường hợp biên (edge case) cụ thể của logic cần kiểm tra, chẳng hạn như chia cho 0 (division-by-zero) trong tính điểm và các điều kiện biên trong các ngưỡng xếp loại (grading thresholds).","C":"Nâng cấp lên một model tier mạnh hơn, vì khả năng suy luận mạnh hơn của nó sẽ xử lý được cả hai loại vấn đề trong một prompt duy nhất và loại bỏ đánh đổi về recall."}},"142":{"q":"Công cụ khám phá codebase của bạn lưu trữ session ID để cho phép các kỹ sư tiếp tục các cuộc điều tra qua nhiều phiên làm việc. Một kỹ sư đã dành một giờ hôm qua để phân tích một module authentication cũ, xây dựng context về kiến trúc và các dependency của nó. Họ muốn tiếp tục vào hôm nay. Session ID vẫn hợp lệ, nhưng hệ thống version control cho thấy 3 trong số 12 file mà agent đã đọc trước đó đã bị một đồng nghiệp chỉnh sửa qua đêm khi merge. Cách tiếp cận nào cân bằng tốt nhất giữa hiệu quả và độ chính xác?","o":{"A":"Resume phiên làm việc và để agent đọc lại ngay lập tức toàn bộ 12 file đã được phân tích trước đó","B":"Resume phiên làm việc mà không thông báo cho agent biết về các file đã thay đổi","C":"Resume phiên làm việc và cho agent biết cụ thể những file nào đã thay đổi để nó phân tích lại có mục tiêu","D":"Bắt đầu một phiên làm việc mới để đảm bảo agent làm việc với trạng thái codebase hiện tại mà không mang theo giả định lỗi thời"}},"143":{"q":"Một kỹ sư nhìn thấy một thông báo lỗi lạ \"SYNC_CONFLICT: entity version mismatch detected\" trong log production nhưng không biết dịch vụ nào trong số 12 service của codebase tạo ra nó. Họ nhờ agent giúp xác định vị trí mã nguồn. Cách tiếp cận exploration nào sẽ tìm ra mã nguồn chịu trách nhiệm một cách hiệu quả nhất?","o":{"A":"Dùng Grep để tìm đoạn văn bản đặc trưng từ thông báo lỗi (như \"SYNC_CONFLICT\" hoặc \"entity version mismatch\"), sau đó Read các file khớp để hiểu ngữ cảnh.","B":"Dùng Glob để tìm các file trong những thư mục thường gắn với việc xử lý lỗi (như errors/, exceptions/, hoặc handlers/) trên tất cả các service, sau đó Read từng file khớp.","C":"Dùng Grep để tìm tất cả các file import module xử lý lỗi của dự án, sau đó Read các file đó để xác định các định nghĩa lỗi tùy chỉnh.","D":"Read file README của dự án và các file cấu hình service để hiểu kiến trúc, sau đó Read một cách có hệ thống các file mã nguồn trong thư mục service."}},"144":{"q":"Bạn đã cấu hình agent Claude của mình với ba MCP server: một cho các thao tác git, một cho quản lý ticket Jira, và một cho documentation search. Khi người dùng yêu cầu agent \"create a branch for JIRA-123 and add documentation links to the ticket\" (tạo một nhánh cho JIRA-123 và thêm các liên kết tài liệu vào ticket), agent truy cập các tool trên các server này như thế nào?","o":{"A":"Agent truy vấn từng server một cách tuần tự để xác định server nào xử lý tool nào, định tuyến các lệnh gọi dựa trên tiền tố tên tool.","B":"Các tool từ tất cả các MCP server đã cấu hình được khám phá tại thời điểm kết nối và có sẵn đồng thời cho agent sử dụng.","C":"Bạn phải chỉ định MCP server nào sẽ dùng cho mỗi lượt (turn), và agent chỉ có thể truy cập tool của một server tại một thời điểm.","D":"Agent tự động chọn server phù hợp nhất dựa trên yêu cầu và chỉ tải các tool của server đó."}},"145":{"q":"Compliance yêu cầu rằng các khoản refund vượt quá $500 phải tự động escalate cho một nhân viên con người - quy tắc này không được để cho model tự quyết định (discretion). Mặc dù có các hướng dẫn system prompt rõ ràng, log production cho thấy agent đôi khi vẫn xử lý trực tiếp các khoản refund giá trị cao (tỷ lệ lỗi 3%). Bạn nên làm thế nào để đạt được compliance được đảm bảo?","o":{"A":"Sửa tool refund để trả về lỗi với thông báo \"Amount exceeds policy limit please escalate\" khi vượt ngưỡng.","B":"Triển khai một hook để chặn các lệnh gọi tool khi số tiền refund vượt quá $500, chặn lại và kích hoạt việc chuyển lên con người xử lý (human escalation).","C":"Tăng cường system prompt bằng ngôn ngữ nhấn mạnh: \"CRITICAL POLICY! Refunds over $500 MUST trigger human escalation. NEVER process these directly!\"","D":"Thêm các ví dụ few-shot vào prompt minh họa hành vi escalation đúng đắn ở các mức số tiền refund khác nhau ($40, $500, $600)."}},"146":{"q":"Log production cho thấy việc xử lý lỗi không nhất quán: khi tool_code thất bại, agent đôi khi retry 5 lần (ngay cả khi tool_id không tồn tại), đôi khi escalate ngay lập tức (quá sớm đối với các vấn đề mạng tạm thời), và đôi khi thêm giải thích thân thiện với người dùng (không phù hợp khi vấn đề là lỗi permission ở backend). Điều tra cho thấy bốn MCP tool trả về các phản hồi lỗi đồng nhất: {\"status\": \"error\", \"content\": \"{\"type\": \"Error\", \"message\": \"Operation failed.\"}\"}. Agent học các loại khác nhau. Cải tiến nào hiệu quả nhất?","o":{"A":"Triển khai logic retry với exponential backoff trong MCP server của bạn cho mọi lỗi, chỉ trả kết quả về cho agent sau khi đã hết số lần retry.","B":"Tạo một MCP tool tên analyze_error mà agent gọi sau bất kỳ lỗi nào để xác định loại lỗi và hành động được đề xuất.","C":"Thêm các ví dụ few-shot vào system prompt minh họa cách diễn giải các mẫu thông báo lỗi và chọn phản hồi phù hợp cho từng loại.","D":"Tăng cường các phản hồi lỗi bằng metadata có cấu trúc. Bao gồm error_category (transient/retriable/permission), lý do (reason), và mô tả nguyên nhân gây ra lỗi."}},"147":{"q":"Log production cho thấy việc xử lý lỗi không nhất quán. Khi tra cứu thông tin, agent đôi khi retry 5+ lần (đáng tiếc, ngay cả khi outer ID không tồn tại), đôi khi escalate ngay lập tức (quá sớm đối với các vấn đề mạng tạm thời), và đôi khi hỏi người dùng để làm rõ (không phù hợp khi vấn đề là lỗi permission ở backend). Điều tra cho thấy MCP tool của bạn trả về các phản hồi lỗi đồng nhất (\"isError\": true, \"context\": {\"type\": \"text\", \"text\": \"Operation failed.\"}). Agent không thể phân biệt giữa các loại lỗi. Cải tiến nào hiệu quả nhất?","o":{"A":"Triển khai logic retry với exponential backoff trong MCP service của bạn cho mọi lỗi, chỉ trả kết quả về cho agent sau khi đã hết số lần retry.","B":"Tạo một MCP tool tên analyze_error mà agent gọi sau bất kỳ lỗi nào để xác định loại lỗi và hành động được đề xuất.","C":"Thêm mười ví dụ shot vào phần huấn luyện conduct_demo của hệ thống để diễn giải ngữ cảnh thông báo lỗi và chọn phản hồi phù hợp cho từng loại.","D":"Trả về metadata lỗi có cấu trúc trong các phản hồi MCP."}},"148":{"q":"Sau khi mở rộng các MCP tool của agent với các khả năng dành riêng cho delivery [apply_promo_code, update_delivery_address, reconcile_delivery], tổng số tool đã tăng từ 1 lên 7. Chúng ta đã quan sát thấy rằng tool selection accuracy của agent hiện đã giảm từ 86% xuống 71%. Phân tích log cho thấy phần lớn các lỗi liên quan đến việc agent lựa chọn giữa các tool có ý nghĩa (semantically) chồng chéo lên nhau — gọi issue_credit trong khi process_refund mới là lựa chọn đúng, và gọi check_delivery_status trong khi order_allready_returns_the_needed_data đã cung cấp dữ liệu cần thiết. Cách tiếp cận nào sẽ loại bỏ về mặt cấu trúc semantic overlap đã được xác định là nguồn gốc của lỗi?","o":{"A":"Hợp nhất các tool trùng lặp về mặt ngữ nghĩa – gộp issue_credit và process_refund thành một tool duy nhất handle_promotions với tham số action, và gộp check_delivery_status vào lookup_order với một cờ tùy chọn include_tracking.","B":"Bật tool search tool với defer_loading cho sáu tool mới, giữ nguyên hai tool gốc luôn được tải sẵn, để agent tự động khám phá các tool chuyên biệt chỉ khi cần.","C":"Thêm các ví dụ few-shot vào system prompt minh họa cách lựa chọn đúng cho từng tool dễ gây nhầm lẫn, chẳng hạn cho thấy khi nào nên dùng issue_credit so với khi nào nên dùng process_refund.","D":"Chia các tool ra cho hai sub-agent — một agent 'financial resolution' có issue_credit, process_refund, return_order, và apply_promo_code, và một agent 'delivery operations' có các tool giao hàng còn lại — với một cơ chế điều phối định tuyến giữa hai agent."}}};
